#!/usr/bin/env tsx
// Golden corpus Test Flights + pass matrix (bundle mc-coverage). Run from a worktree on the primary (only ssh to node-2;
// the server itself boots on node-2 under the Test Flight runner, one flight at a time).
//
//   1. compile on node-2:   scripts/devhost run --lock -- node services/modbuilder/golden/harness.js
//   2. fly one version:     npx tsx scripts/cyrus/golden-flight.ts fly 1.21.11 [--out DIR] [--remote-out DIR]   (starter bank: --remote-out /tank/nxeon-build/tmp/testflight/starter-bank)
//      boots ONE Paper server with every golden jar that compiled for that version and runs each plugin's RCON checks
//      (golden.json "rcon"); writes <out>/flight-<version>.json (the raw report + a per-plugin verdict).
//   3. pass matrix:         npx tsx scripts/cyrus/golden-flight.ts results [--out DIR]
//      merges node-2's compile.json with the flight files into services/modbuilder/golden/results.json (committed)
//      and prints the per-archetype/per-version JSON for /root/agent-notes/cyrus-research/mc-coverage-flights-*.json.
import { execFileSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { runTestFlight, NODE2 } from "../../lib/cyrus/testflight/client";
import type { TestFlightReport, TestFlightSpec } from "../../lib/cyrus/testflight/types";


/** One flight at a time on node-2: when another agent's flight holds the runner lock, wait and retry (max ~20 min). */
async function flyWhenFree(spec: TestFlightSpec) {
  for (let i = 0; ; i++) {
    const r = await runTestFlight(spec);
    if (r.report.status !== "busy" || i >= 40) return r;
    await new Promise((res) => setTimeout(res, 30000));
  }
}

const ROOT = path.resolve(__dirname, "../..");
const argv = process.argv.slice(2);
