            case "list" -> { for (BossDef d : b.defs().values()) say(sender, d.describeDef(), NamedTextColor.AQUA); if (b.defs().isEmpty()) say(sender, "No bosses.", NamedTextColor.GRAY); }
            case "status" -> {
                if (b.live().isEmpty()) say(sender, "No bosses alive.", NamedTextColor.GRAY);
                for (BossInstance i : new ArrayList<>(b.live())) say(sender, b.statusLine(i), NamedTextColor.AQUA);
                for (String s : b.lastEvents()) say(sender, "last: " + s, NamedTextColor.GRAY);
            }
            case "check" -> { for (String line : check()) say(sender, line, line.contains("FAIL") ? NamedTextColor.RED : NamedTextColor.AQUA); }
