// Cyrus behaviour oracle (oracle-1): derive the EXPECTATIONS of one build. Pure, deterministic, no model call.
//
// Sources, in order: plugin.yml (the mod enables, each command answers, a `give` sub-command gives something, the reload
// command), the designer specs (items: given + abilities + passives + recipe; menus: open + buttons; quests: start /
// complete; bosses: spawn; HUDs: shown; config: a value change reaches the game after reload), the data pack specs
// (recipes unlock, loot tables give, advancements grant + reward), the creature rig specs. Every expectation carries its
// probe; what the oracle cannot try honestly is listed as not_testable with the reason (never silently dropped).
//
// Probes only use the typed playtest steps (lib/cyrus/playtest/plan.ts) and console commands over RCON; the test player is
// "{bot}" (replaced by the runner). Targets are summoned with the tag nxo_t (no AI, silent, never despawn) in front of
// the player and removed afterwards.
import { parseYaml, asMap, asStr, type YamlValue } from "../../inventory/yaml";
import { readDescriptor } from "../../inventory/descriptor";
import { getYamlValue, setYamlValue } from "../../config/yamldoc";
import { reloadCommandOf } from "../../config/infer";
import { stepErrors, type PlaytestStep } from "../../playtest/plan";
import { ORACLE_LIMITS, type Expectation, type ExpectationKind, type OracleInput, type ProbeRcon, type ProbeStep, type Role } from "./types";

// ------------------------------------------------------------------------------------------------------------ helpers
type Cmd = { label: string; usage: string; description: string; permDefault: "true" | "false" | "op" | "not op" };
type Obj = Record<string, unknown>;
const isObj = (v: unknown): v is Obj => !!v && typeof v === "object" && !Array.isArray(v);
const arr = (v: unknown): unknown[] => (Array.isArray(v) ? v : []);
const str = (v: unknown): string | null => (typeof v === "string" && v.trim() ? v : null);
const bare = (id: string) => String(id).toLowerCase().replace(/^minecraft:/, "");
const S = (role: Role, step: PlaytestStep, want?: string[], wantNot?: string[]): ProbeStep => ({ role, step, ...(want ? { want } : {}), ...(wantNot ? { wantNot } : {}) });
const server = (command: string) => ({ kind: "server" as const, command });

/** The visible text of a StyledText / string / list of them. */
export function textOf(v: unknown): string {
  if (typeof v === "string") return v;
  if (Array.isArray(v)) return v.map(textOf).join("");
  if (isObj(v) && typeof v.text === "string") return v.text;
  return "";
}

/** The longest literal piece of a message (placeholders such as {player} removed), for a "contains" check. null = too short to be a fair check. */
export function literal(text: string, max = 60): string | null {
  const parts = String(text).split(/\{[a-z_]+\}|%[a-z_]+%|<[a-z_]+>|\n/i).map((p) => p.trim()).filter(Boolean);
  const best = parts.sort((a, b) => b.length - a.length)[0] ?? "";
  if (best.length < 3) return null;
  return best.length > max ? best.slice(0, max).trim() : best;
}

/** Commands declared in plugin.yml (with usage text and the default of their permission). */
export function commandsOf(pluginYml: string | null): Cmd[] {
  if (!pluginYml) return [];
  const root = asMap(parseYaml(pluginYml).value);
  const cmds = asMap(root?.commands as YamlValue);
  if (!cmds) return [];
  const desc = readDescriptor(pluginYml, "plugin.yml");
  const out: Cmd[] = [];
  for (const [label, def] of Object.entries(cmds)) {
    if (!/^[a-z0-9_-]{1,32}$/i.test(label)) continue;
    const d = asMap(def as YamlValue);
    const perm = asStr(d?.permission as YamlValue);
    const pd = perm ? desc.permissions.find((p) => p.name === perm)?.default ?? "op" : "true";
    out.push({ label: label.toLowerCase(), usage: asStr(d?.usage as YamlValue) ?? "", description: asStr(d?.description as YamlValue) ?? "", permDefault: pd });
  }
  return out;
}

/** "give <a|b|c>" in a usage string -> "a"; "give" with no item list -> "" ; no give -> null. */
export function giveArgOf(usage: string): string | null {
  const u = usage.replace(/\s+/g, " ");
  if (!/\bgive\b/i.test(u)) return null;
  const m = /\bgive\s+<([a-z0-9_|:-]+)>/i.exec(u);
  if (m && m[1].includes("|")) return m[1].split("|")[0].toLowerCase();
  if (m) return null; // give <item>: a placeholder, the oracle does not know an item name
  if (/\bgive\s+[[(]?(player|target)/i.test(u) || /\bgive\b\s*($|[|>\])])/i.test(u)) return "";
  return null;
}

const TARGET_FOR: Record<string, { type: string; health: number }> = {
  hostile: { type: "husk", health: 20 }, living: { type: "husk", health: 20 }, animal: { type: "pig", health: 10 },
};
const TARGET_HEALTH: Record<string, number> = { husk: 20, zombie: 20, pig: 10, cow: 10, sheep: 8, chicken: 4, skeleton: 20, spider: 16, villager: 20, wolf: 8, iron_golem: 100, creeper: 20, rabbit: 3, fox: 10, goat: 10 };
const PROJECTILE_ENTITY: Record<string, string> = { snowball: "snowball", arrow: "arrow", small_fireball: "small_fireball", wind_charge: "wind_charge" };

/** Summon one marked target in front of the player (no AI, silent, persistent) and prove it exists before the act. */
function targetSteps(type: string): ProbeStep[] {
  return [
    S("setup", server(`execute at {bot} run summon minecraft:${type} ^ ^ ^3 {Tags:["nxo_t"],NoAI:1b,Silent:1b,PersistenceRequired:1b}`), ["Summoned"]),
    S("setup", server(`execute if entity @e[tag=nxo_t]`), ["Test passed"]),
  ];
}
const cleanupTargets = (): ProbeStep => S("cleanup", server("kill @e[tag=nxo_t]"));
/** Damaged or gone (killed): health is no longer the full health it was summoned with. */
const damagedCheck = (type: string): ProbeStep => S("probe", server(`execute unless entity @e[tag=nxo_t,nbt={Health:${TARGET_HEALTH[type].toFixed(1)}f}]`), ["Test passed"]);

// ---------------------------------------------------------------------------------------------------- observables
type Obs =
  | { k: "chat"; text: string } | { k: "title"; text: string } | { k: "effect"; effect: string } | { k: "item"; item: string; name?: string }
  | { k: "damage" } | { k: "particle"; particle: string } | { k: "sound"; sound: string } | { k: "moved" } | { k: "entity"; type: string };
type Walk = { obs: Obs[]; target: boolean; delayMs: number; chance: number | null; untestable: string | null };

const RANK: Record<Obs["k"], number> = { chat: 0, title: 0, effect: 0, item: 0, damage: 1, particle: 2, sound: 3, entity: 4, moved: 5 };

/** Conditions the test can satisfy (or that hold anyway). Anything else makes the branch / ability untestable. */
function condOk(c: Obj, ctx: { sneaking: boolean; world: string }): { ok: boolean; why?: string; chance?: number; time?: number; target?: string } {
  const neg = c.negate === true;
  switch (c.type) {
    case "cooldown_ready": case "charges_available": return { ok: !neg };
    case "item_identity": return c.slot === "main_hand" && !neg ? { ok: true } : { ok: false, why: "it needs an item in the off hand" };
    case "sneaking": return { ok: neg ? !ctx.sneaking : ctx.sneaking, why: "it needs a sneak state the trigger does not give" };
    case "has_permission": return { ok: !neg };
    case "world_in": { const has = arr(c.worlds).includes(ctx.world); return { ok: neg ? !has : has, why: "it only works in another world" }; }
    case "random_chance": { const ch = Number(c.chance); return ch >= 1 && !neg ? { ok: true } : { ok: false, chance: ch, why: `it only happens by chance (${Math.round(ch * 100)}%)` }; }
    case "time_of_day": return neg ? { ok: false, why: "it needs a time of day the test does not set" } : { ok: true, time: Number(c.from) };
    case "target_is": {
      if (neg) return { ok: false, why: "it needs a target that is NOT a given kind" };
      const types = arr(c.types).map((t) => bare(String(t)));
      const kinds = arr(c.kinds).map(String);
      const t = types.find((x) => TARGET_HEALTH[x]) ?? (kinds.includes("player") ? null : TARGET_FOR[kinds.find((k) => TARGET_FOR[k]) ?? "living"]?.type ?? null);
      return t ? { ok: true, target: t } : { ok: false, why: "it needs a target type the test cannot summon" };
    }
    default: return { ok: false, why: `it depends on ${String(c.type).replace(/_/g, " ")}` };
  }
}

function walkActions(actions: unknown[], who: "self" | "target", ctx: { sneaking: boolean; world: string; items: Map<string, { base: string; name: string }> }, w: Walk, depth = 0) {
  if (depth > 6) return;
  for (const raw of actions) {
    if (!isObj(raw)) continue;
    const a = raw;
    const to = (a.to ?? a.target ?? "self") as string;
    switch (a.type) {
      case "send_message": case "actionbar": { const l = literal(String(a.text ?? "")); if (l && who === "self" && to === "self") w.obs.push({ k: "chat", text: l }); break; }
      case "title": { const l = literal(String(a.title ?? "")); if (l && who === "self" && to === "self") w.obs.push({ k: "title", text: l }); break; }
      case "potion_effect": if (who === "self" && (a.target ?? "self") === "self") w.obs.push({ k: "effect", effect: String(a.effect) }); break;
      case "give_item": { const it = String(a.item ?? ""); const d = ctx.items.get(it); w.obs.push(d ? { k: "item", item: d.base, name: d.name } : { k: "item", item: bare(it) }); break; }
      case "damage": if ((who === "target" || a.target === "target" || a.target == null) && a.target !== "self") { w.target = true; w.obs.push({ k: "damage" }); } break;
      case "hitscan": case "beam": w.target = true; w.obs.push({ k: "damage" }); if (a.tracer || a.particle) w.obs.push({ k: "particle", particle: String(a.tracer ?? a.particle) }); break;
      case "area_blast": w.target = true; w.obs.push({ k: "damage" }); if (a.particle) w.obs.push({ k: "particle", particle: String(a.particle) }); break;
      case "spawn_particles": w.obs.push({ k: "particle", particle: String(a.particle) }); break;
      case "play_sound": w.obs.push({ k: "sound", sound: String(a.sound) }); break;
      case "teleport_short": w.obs.push({ k: "moved" }); break;
      case "knockback": case "pull_to": case "push_from": if ((a.target ?? "target") === "self" && who === "self") w.obs.push({ k: "moved" }); break;
      case "launch_projectile": { const e = PROJECTILE_ENTITY[String(a.kind)]; if (e) w.obs.push({ k: "entity", type: e }); break; }
      case "query_nearby": case "query_marked": w.target = true; walkActions(arr(a.actions), "target", ctx, w, depth + 1); break;
      case "delayed": w.delayMs = Math.max(w.delayMs, Math.min(8000, Number(a.delayTicks) * 50)); walkActions(arr(a.actions), who, ctx, w, depth + 1); break;
      case "branch": {
        const conds = arr(a.if).filter(isObj).map((c) => condOk(c, ctx));
        if (conds.every((c) => c.ok)) walkActions(arr(a.then), who, ctx, w, depth + 1);
        else {
          const ch = conds.find((c) => c.chance != null);
          if (ch) w.chance = ch.chance ?? null;
          // the else branch runs when the condition fails: only usable when the condition is certainly false in the test
        }
        break;
      }
      default: break; // set_cooldown, consume_charge, apply_mark, capture_mob, vein_break, heal: no outside observable here
    }
  }
}

// ---------------------------------------------------------------------------------------------------- the builder
class Builder {
  list: Expectation[] = [];
  add(kind: ExpectationKind, title: string, source: Expectation["source"], probe: Expectation["probe"], notTestable?: string) {
    if (this.list.length >= ORACLE_LIMITS.expectations) return null;
    const e: Expectation = { id: `E${this.list.length + 1}`, kind, title: title.slice(0, 200), source, origin: "derived", probe: notTestable ? null : probe, ...(notTestable ? { notTestable } : {}) };
    this.list.push(e);
    return e;
  }
}

export type DeriveOptions = { env?: Record<string, string | undefined>; sentinel?: string };

/** Derive the expectations of one build (deterministic for the same input). */
export function deriveExpectations(input: OracleInput, opts: DeriveOptions = {}): Expectation[] {
  const b = new Builder();
  const name = input.pluginName;
  const ns = input.namespace ?? null;
  const cmds = commandsOf(input.pluginYml);
  const designs = (input.designs ?? []).filter((d) => isObj(d.spec));
  const kindOf = (s: Obj) => (s.kind === undefined || s.kind === "item" ? "item" : String(s.kind));
  const items = designs.filter((d) => kindOf(d.spec as Obj) === "item").map((d) => d.spec as Obj);
  const menus = designs.filter((d) => kindOf(d.spec as Obj) === "menu").map((d) => d.spec as Obj);
  const quests = designs.filter((d) => kindOf(d.spec as Obj) === "quest").map((d) => d.spec as Obj);
  const bosses = designs.filter((d) => kindOf(d.spec as Obj) === "boss").map((d) => d.spec as Obj);
  const huds = designs.filter((d) => kindOf(d.spec as Obj) === "hud").map((d) => d.spec as Obj);
  const others = designs.filter((d) => ["encounter", "motion"].includes(kindOf(d.spec as Obj)));
  const isDesigner = designs.length > 0;
  // a designer mod has one command: give / list / params / reload (+ menu / quests / boss / hud)
  const dl = isDesigner ? (cmds.find((c) => /give\|list|menu\||boss\||hud\|/.test(c.usage)) ?? cmds[0] ?? null) : null;
  const L = dl?.label ?? null;
  const itemMap = new Map(items.map((it) => [String(it.id), { base: bare(String(it.base ?? "")), name: textOf(it.name) }]));
  const sentinel = opts.sentinel ?? `#${hash6(`${name}|${input.version}|${designs.map((d) => d.name).join(",")}`)}`;

  // 1. the mod enables (the boot check of this same flight)
  b.add("mod_enables", `${name} starts on the server`, { from: "plugin.yml", ref: "name" }, { boot: "plugins_enabled" });

  // 2. every command answers (console, no arguments): no "internal error", not unknown
  for (const c of cmds.slice(0, ORACLE_LIMITS.commands)) {
    b.add("command_responds", `The /${c.label} command answers without an error`, { from: "plugin.yml", ref: `commands.${c.label}` },
      { rcon: [{ role: "check", check: { command: c.label, required: false }, wantNot: ["An internal error occurred", "Unknown or incomplete command", "Unknown command"] }] });
  }

  // 3. designer items: given, abilities, passives, recipe
  const configReloadHosts: { exp: Expectation; path: string; value: string; check: (s: string) => ProbeStep }[] = [];
  for (const it of items.slice(0, ORACLE_LIMITS.items)) {
    const id = String(it.id), base = bare(String(it.base ?? "")), nm = textOf(it.name);
    if (!L) { b.add("item_given", `${nm || id} can be given`, { from: "design", ref: id }, null, "the mod has no command to give its items"); continue; }
    b.add("item_given", `/${L} give ${id} gives the ${nm || id}`, { from: "design", ref: id }, {
      rcon: [{ role: "check", check: { command: `${L} list`, required: false }, want: [`${id}: identity=ok`] }],
      bot: { op: false, steps: [
        S("act", server(`${L} give ${id} {bot}`), ["Gave"]),
        S("check", { kind: "expect_inventory", item: base, ...(nm ? { name: nm.slice(0, 100) } : {}), withinMs: 2500 }),
      ] },
    });
    // abilities
    const perms = new Map(arr(it.permissions).filter(isObj).map((p) => [String(p.node), String(p.default)]));
    for (const ab of arr(it.abilities).filter(isObj).slice(0, ORACLE_LIMITS.abilitiesPerItem)) {
      const abName = String(ab.name ?? ab.id), trig = isObj(ab.trigger) ? ab.trigger : {};
      const title = `${nm || id}: "${abName}" works (${String(trig.type ?? "?").replace(/_/g, " ")})`;
      const src = { from: "design" as const, ref: `${id}.abilities.${ab.id}` };
      const r = abilityProbe(L, id, base, nm, ab, trig, perms, itemMap);
      if ("why" in r) { b.add("ability_effect", title, src, null, r.why); continue; }
      const e = b.add("ability_effect", title, src, { bot: { op: r.op, steps: r.steps } });
      // a message of this ability, extended in config.yml + reload, must reach the game (config_reload attaches here)
      if (e && r.messagePath && configKeyExists(input.configYml, `items.${id}.abilities.${String(ab.id)}.${r.messagePath.path}`)) {
        configReloadHosts.push({ exp: e, path: `items.${id}.abilities.${String(ab.id)}.${r.messagePath.path}`, value: r.messagePath.value, check: (s) => S("check", { kind: "expect_chat", contains: [s], withinMs: 2500 }) });
      }
    }
    for (const p of arr(it.passives).filter(isObj).slice(0, 2)) {
      const eff = String(p.effect), slot = String(p.slot ?? "main_hand");
      if (slot === "off_hand") { b.add("passive_effect", `Holding the ${nm || id} gives ${eff.replace(/_/g, " ")}`, { from: "design", ref: `${id}.passives` }, null, "it needs the item in the off hand"); continue; }
      b.add("passive_effect", `Holding the ${nm || id} gives ${eff.replace(/_/g, " ")}`, { from: "design", ref: `${id}.passives` }, { bot: { steps: [
        S("setup", server(`${L} give ${id} {bot}`), ["Gave"]),
        S("setup", { kind: "hold", item: base }),
        S("check", { kind: "expect_effect", effect: eff, withinMs: 3500 }),
      ] } });
    }
    if (isObj(it.recipe) && ns) {
      b.add("recipe_registered", `The ${nm || id} has a crafting recipe the game knows`, { from: "design", ref: `${id}.recipe` }, { bot: { steps: [
        S("probe", server(`recipe give {bot} ${ns}:${id}`), ["Unlocked"]),
        S("check", { kind: "expect_no_chat", contains: ["An internal error occurred"], forMs: 300 }),
      ] } });
    }
  }

  // 4. menus: opens with its buttons; up to two buttons do what they say
  const menuOf = new Map(menus.map((m) => [String(m.id), m]));
  for (const m of menus.slice(0, ORACLE_LIMITS.menus)) {
    const id = String(m.id), title = String(m.title ?? id);
    const src = { from: "design" as const, ref: `menu.${id}` };
    const openWith = isObj(m.openWith) ? m.openWith : {};
    if (!L || openWith.command === false) { b.add("menu_opens", `The "${title}" menu opens`, src, null, openWith.item ? "it opens from an item, not a command (not driven yet)" : openWith.npc ? "it opens from an NPC, not a command" : "the mod has no menu command"); continue; }
    const buttons = m.style === "chest" ? arr(m.buttons).filter(isObj).filter((x) => !(x.permission && x.hideWithoutPermission)) : [];
    const slots = buttons.slice(0, 6).map((x) => ({ slot: Number(x.slot), item: bare(String((x.icon as Obj)?.material ?? "")), ...(textOf((x.icon as Obj)?.name) ? { name: textOf((x.icon as Obj)?.name).slice(0, 100) } : {}) })).filter((x) => Number.isInteger(x.slot) && x.slot >= 0 && x.slot <= 89 && x.item);
    const open: ProbeStep = S("act", { kind: "command", text: `/${L} menu ${id}` });
    const n = m.style === "chest" ? buttons.length : arr(m.choices).length;
    const e = b.add("menu_opens", `/${L} menu ${id} opens "${title}" with ${n} button${n === 1 ? "" : "s"}`, src, { bot: { steps: [
      open,
      S("check", { kind: "expect_window", title: [title.slice(0, 200)], minItems: Math.min(90, n), ...(slots.length ? { slots } : {}), withinMs: 3000 }),
    ] } });
    if (e && configKeyExists(input.configYml, `menus.${id}.title`) && (title + " " + sentinel).length <= 32) {
      configReloadHosts.unshift({ exp: e, path: `menus.${id}.title`, value: title, check: (s) => S("check", { kind: "expect_window", title: [s], withinMs: 2000 }) });
    }
    // buttons: give_item > send_message > open_menu > potion_effect > sound
    const ranked = buttons.map((x) => ({ x, a: arr(x.actions).filter(isObj) }))
      .map((v) => ({ ...v, score: v.a.some((a) => a.type === "give_item") ? 0 : v.a.some((a) => a.type === "send_message") ? 1 : v.a.some((a) => a.type === "open_menu") ? 2 : v.a.some((a) => a.type === "potion_effect") ? 3 : v.a.some((a) => a.type === "play_sound") ? 4 : 9 }))
      .filter((v) => v.score < 9).sort((p, q) => p.score - q.score).slice(0, ORACLE_LIMITS.clicksPerMenu);
    for (const { x, a } of ranked) {
      const iconName = textOf((x.icon as Obj)?.name) || `slot ${x.slot}`;
      const t = `In "${title}", clicking "${iconName}" works`;
      const cost = isObj(x.cost) ? x.cost : null;
      const steps: ProbeStep[] = [];
      let costItem: string | null = null;
      if (cost?.type === "item") {
        const ci = String(cost.item), cnt = Math.max(1, Math.min(2304, Number(cost.count) || 1)), d = itemMap.get(ci);
        if (d) steps.push(S("setup", server(`${L} give ${ci} {bot} ${Math.min(64, cnt)}`), ["Gave"]));
        else { steps.push(S("setup", server(`give {bot} ${ci.includes(":") ? ci : `minecraft:${ci}`} ${cnt}`), ["Gave"])); costItem = bare(ci); }
      } else if (cost?.type === "xp_levels") steps.push(S("setup", server(`xp add {bot} ${Number(cost.levels) || 1} levels`), ["Gave"]));
      else if (cost?.type === "economy") { b.add("menu_click", t, { from: "design", ref: `menu.${id}.slot${x.slot}` }, null, "it costs server money (Vault), which the test server does not have"); continue; }
      steps.push(open, S("setup", { kind: "expect_window", title: [title.slice(0, 200)], withinMs: 3000 }), S("act", { kind: "click_window", slot: Number(x.slot) }));
      const give = a.find((y) => y.type === "give_item"), msg = a.find((y) => y.type === "send_message" || y.type === "actionbar"), om = a.find((y) => y.type === "open_menu"), pe = a.find((y) => y.type === "potion_effect"), snd = a.find((y) => y.type === "play_sound");
      if (give) {
        const gi = String(give.item), d = itemMap.get(gi);
        steps.push(S("check", { kind: "expect_inventory", item: d ? d.base : bare(gi), count: Math.max(1, Number(give.count) || 1), ...(d?.name ? { name: d.name.slice(0, 100) } : {}), withinMs: 2500 }));
        if (costItem && costItem !== (d ? d.base : bare(gi))) steps.push(S("check", { kind: "expect_no_item", item: costItem, forMs: 400 }));
      } else if (msg && literal(String(msg.text ?? ""))) steps.push(S("check", { kind: "expect_chat", contains: [literal(String(msg.text))!], withinMs: 2500 }));
      else if (om && menuOf.get(String(om.menu))) steps.push(S("check", { kind: "expect_window", title: [String(menuOf.get(String(om.menu))!.title).slice(0, 200)], withinMs: 2500 }));
      else if (pe) steps.push(S("check", { kind: "expect_effect", effect: String(pe.effect), withinMs: 2500 }));
      else if (snd) steps.push(S("check", { kind: "expect_sound", sound: String(snd.sound), withinMs: 2500 }));
      else { b.add("menu_click", t, { from: "design", ref: `menu.${id}.slot${x.slot}` }, null, "its action has nothing the test player can see"); continue; }
      steps.push(S("cleanup", { kind: "close_window" }));
      b.add("menu_click", t, { from: "design", ref: `menu.${id}.slot${x.slot}` }, { bot: { steps } });
    }
  }

  // 5. quests: complete it when every objective can be simulated, otherwise prove it starts
  for (const q of quests.slice(0, ORACLE_LIMITS.quests)) {
    const id = String(q.id), title = String(q.title ?? id), src = { from: "design" as const, ref: `quest.${id}` };
    if (!L) { b.add("quest_progress", `The "${title}" quest can be done`, src, null, "the mod has no quest command"); continue; }
    if (q.start === "menu") { b.add("quest_progress", `The "${title}" quest can be done`, src, null, "it starts from a menu button only (not driven yet)"); continue; }
    if (arr(q.requires).length) { b.add("quest_progress", `The "${title}" quest can be done`, src, null, "it needs other quests completed first"); continue; }
    const sim = questSim(L, q, itemMap, menuOf);
    const start: ProbeStep = S("act", { kind: "command", text: `/${L} quests start ${id}` });
    if (sim.steps && !q.branches) {
      const rewards: ProbeStep[] = [];
      for (const r of arr(q.rewards).filter(isObj)) {
        if (r.type === "give_item") { const d = itemMap.get(String(r.item)); rewards.push(S("check", { kind: "expect_inventory", item: d ? d.base : bare(String(r.item)), ...(d?.name ? { name: d.name.slice(0, 100) } : {}), withinMs: 2500 })); break; }
      }
      b.add("quest_progress", `The "${title}" quest can be completed${rewards.length ? " and pays its reward" : ""}`, src, { bot: { op: false, steps: [
        S("setup", { kind: "server", command: "tp {bot} 0.5 -60 0.5" }, ["Teleported"]),
        start, ...sim.steps,
        S("check", { kind: "expect_chat", contains: [`Quest complete: ${title}`.slice(0, 200)], withinMs: 4000 }),
        ...rewards,
      ] } });
    } else {
      b.add("quest_progress", `The "${title}" quest can be started${sim.why ? ` (completing it is not tested: ${sim.why})` : ""}`, src, { bot: { op: false, steps: [
        start, S("act", { kind: "command", text: `/${L} quests` }),
        S("check", { kind: "expect_chat", contains: [`${id} - ${title}: Active`.slice(0, 200)], withinMs: 2500 }),
      ] } });
    }
  }

  // 6. bosses: spawn by command, the entity is there and its boss bar shows
  for (const bo of bosses.slice(0, ORACLE_LIMITS.bosses)) {
    const id = String(bo.id), nm = textOf(bo.name) || id, ent = bare(String(bo.entity ?? "")), src = { from: "design" as const, ref: `boss.${id}` };
    const spawnCmd = !isObj(bo.spawn) || bo.spawn.command !== false;
    if (!L || !ns || !spawnCmd) { b.add("boss_spawns", `${nm} can be summoned`, src, null, !spawnCmd ? "it is summoned by an item or an encounter, not a command" : "the mod has no boss command"); continue; }
    const e = b.add("boss_spawns", `/${L} boss spawn ${id} summons ${nm}${bo.bossBar ? " with its boss bar" : ""}`, src, { bot: { op: false, steps: [
      S("setup", server("effect give {bot} minecraft:resistance 60 4 true"), ["Applied"]),
      S("act", server(`${L} boss spawn ${id} spawn`), ["Spawned"]),
      S("probe", server(`execute if entity @e[tag=${ns}.boss.${id}]`), ["Test passed"]),
      ...(bo.bossBar ? [S("check", { kind: "expect_bossbar", contains: [nm.slice(0, 200)], withinMs: 3000 })] : [S("check", { kind: "expect_entity", type: ent, withinMs: 3000 })]),
      S("cleanup", server(`${L} boss despawn all`)),
    ] } });
    if (e && configKeyExists(input.configYml, `bosses.${id}.name`) && (nm + " " + sentinel).length <= 60 && bo.bossBar) {
      configReloadHosts.push({ exp: e, path: `bosses.${id}.name`, value: nm, check: () => S("check", { kind: "expect_bossbar", contains: [sentinel], withinMs: 2500 }) });
    }
  }

  // 7. HUDs: what the player is shown (always, or while holding the item)
  for (const h of huds.slice(0, 2)) {
    const id = String(h.id), src = { from: "design" as const, ref: `hud.${id}` };
    const r = hudProbe(L, h, itemMap);
    if ("why" in r) b.add("hud_visible", `The HUD "${id}" shows`, src, null, r.why);
    else b.add("hud_visible", `The HUD "${id}" shows its ${r.channel}${r.holding ? ` while holding the ${r.holding}` : ""}`, src, { bot: { steps: r.steps } });
  }
  for (const o of others.slice(0, 4)) {
    const k = kindOf(o.spec as Obj);
    b.add(k === "encounter" ? "boss_spawns" : "hud_visible", `The ${k} "${o.name}" plays`, { from: "design", ref: `${k}.${o.name}` }, null, `${k} designs are not driven by the oracle yet`);
  }

  // 8. a config.yml change reaches the game after /<cmd> reload (designer mods: the value is extended with a marker)
  if (L && input.configYml) {
    const host = configReloadHosts[0];
    if (host) {
      const changed = setYamlValue(input.configYml, host.path, `${host.value} ${sentinel}`.slice(0, 120));
      const restored = input.configYml;
      if (changed.ok && changed.changed && Buffer.byteLength(changed.text) <= 64 * 1024) {
        const file = `plugins/${name}/config.yml`;
        b.add("config_reload", `Changing ${host.path} in config.yml and running /${L} reload changes the game`, { from: "config.yml", ref: host.path }, {
          rcon: [{ role: "act", check: { command: `${L} reload`, writeFile: { path: file, content: changed.text }, required: false }, want: ["reloaded"], wantNot: ["An internal error occurred"] }],
          bot: { attachTo: host.exp.id, steps: [host.check(sentinel)] },
        });
        void restored;
      } else b.add("config_reload", `A config.yml change reaches the game after /${L} reload`, { from: "config.yml", ref: host.path }, null, "the oracle could not edit the config file safely");
    } else if (isDesigner) b.add("config_reload", `A config.yml change reaches the game after /${L} reload`, { from: "config.yml", ref: "-" }, null, "no setting of this mod has an effect the test player can see");
  }

  // 9. model-written plugins: a `give` sub-command gives something; the reload command answers
  if (!isDesigner) {
    for (const c of cmds) {
      const g = giveArgOf(c.usage);
      if (g === null) continue;
      const cmd = g ? `/${c.label} give ${g}` : `/${c.label} give`;
      b.add("item_given", `${cmd} gives the player an item`, { from: "plugin.yml", ref: `commands.${c.label}.usage` }, { bot: { op: true, steps: [
        S("act", { kind: "command", text: cmd }),
        S("probe", server("execute if data entity {bot} Inventory[0]"), ["Test passed"]),
        S("check", { kind: "expect_no_chat", contains: ["An internal error occurred"], forMs: 300 }),
      ] } });
      break;
    }
    const rc = reloadCommandOf(input.pluginYml ?? undefined);
    if (rc) b.add("reload_command", `${rc} reloads the settings without an error`, { from: "plugin.yml", ref: rc }, {
      rcon: [{ role: "check", check: { command: rc.slice(1), required: false }, wantNot: ["An internal error occurred", "Unknown or incomplete command", "Unknown command"], nonEmpty: true }],
    });
  }

  // 10. data packs that fly with the mod: recipes unlock, loot tables give items, advancements grant (+ their XP reward)
  for (const dp of input.datapacks ?? []) {
    if (!isObj(dp.spec) || !ns) continue;
    const res = arr(dp.spec.resources).filter(isObj);
    for (const r of res.filter((x) => x.type === "recipe").slice(0, ORACLE_LIMITS.recipes)) {
      const rid = `${ns}:${String(r.id)}`, out = isObj(r.recipe) && isObj(r.recipe.result) ? bare(String(r.recipe.result.item ?? "")) : "";
      b.add("recipe_registered", `The recipe ${String(r.id).replace(/_/g, " ")}${out ? ` (makes ${out.replace(/_/g, " ")})` : ""} is in the game`, { from: "datapack", ref: `${dp.name}:${r.id}` }, { bot: { steps: [
        S("probe", server(`recipe give {bot} ${rid}`), ["Unlocked"]),
        S("check", { kind: "expect_no_chat", contains: ["An internal error occurred"], forMs: 300 }),
      ] } });
    }
    for (const r of res.filter((x) => x.type === "loot_table").slice(0, ORACLE_LIMITS.lootTables)) {
      b.add("loot_gives", `The loot table ${String(r.id)} gives items`, { from: "datapack", ref: `${dp.name}:${r.id}` }, { bot: { steps: [
        S("setup", server(`loot give {bot} loot ${ns}:${String(r.id)}`)),
        S("setup", server(`loot give {bot} loot ${ns}:${String(r.id)}`)),
        S("probe", server("execute if data entity {bot} Inventory[0]"), ["Test passed"]),
        S("check", { kind: "expect_no_chat", contains: ["An internal error occurred"], forMs: 300 }),
      ] } });
    }
    for (const r of res.filter((x) => x.type === "advancement").slice(0, ORACLE_LIMITS.advancements)) {
      const adv = isObj(r.advancement) ? r.advancement : {};
      const xp = isObj(adv.rewards) ? Number(adv.rewards.experience) || 0 : 0;
      const t = textOf(isObj(adv.display) ? adv.display.title : "") || String(r.id);
      b.add("advancement_reward", `The advancement "${t}" can be granted${xp ? ` and gives ${xp} XP` : ""}`, { from: "datapack", ref: `${dp.name}:${r.id}` }, { bot: { steps: [
        S("setup", server("xp set {bot} 0 points")),
        S("probe", server(`advancement grant {bot} only ${ns}:${String(r.id)}`), ["Granted"]),
        ...(xp ? [S("probe", server("xp query {bot} points"), [`has ${xp} experience points`])] : []),
        S("check", { kind: "expect_no_chat", contains: ["An internal error occurred"], forMs: 300 }),
      ] } });
    }
  }

  // 11. creatures: how one appears is AI-written code; only a declared spawn command can be driven
  for (const c of (input.creatures ?? []).slice(0, 3)) {
    const engine = (input.engines ?? []).some((e) => e.toLowerCase() === "bettermodel");
    const spawnCmd = cmds.find((x) => /\b(spawn|summon)\b/i.test(x.usage));
    const t = `The creature "${c.name}" appears with its model`;
    if (!engine) b.add("creature_spawns", t, { from: "rig", ref: c.name }, null, "the creature engine (BetterModel) is not part of this flight");
    else if (!spawnCmd) b.add("creature_spawns", t, { from: "rig", ref: c.name }, null, "how the creature appears is written by the AI; there is no spawn command to drive");
    else b.add("creature_spawns", t, { from: "rig", ref: c.name }, null, "a creature's model is only drawn by a real client (not part of a server test)");
  }

  // 12. optional model-authored extras (off by default)
  if ((opts.env ?? process.env).CYRUS_TESTFLIGHT_ORACLE_EXTRAS === "1") for (const x of (input.extra ?? []).slice(0, 4)) addExtra(b, x);
  return b.list;
}

function addExtra(b: Builder, raw: unknown) {
  if (!isObj(raw) || typeof raw.title !== "string" || !Array.isArray(raw.steps)) return;
  const steps = raw.steps.slice(0, 16);
  const errs = steps.flatMap((s, i) => stepErrors(s, `extra.steps[${i}]`));
  const proves = steps.some((s) => String((s as Obj)?.kind ?? "").startsWith("expect_"));
  const e = b.add("model_extra", raw.title.slice(0, 200), { from: "model", ref: "extra" }, errs.length || !proves ? null : { bot: { steps: steps.map((s) => S(String((s as Obj).kind).startsWith("expect_") ? "check" : "act", s as PlaytestStep)) } }, errs.length ? `the suggested test is invalid: ${errs[0]}` : !proves ? "the suggested test checks nothing" : undefined);
  if (e) e.origin = "model";
}

// --------------------------------------------------------------------------------------------- ability probes
type AbilityProbe = { steps: ProbeStep[]; op: boolean; messagePath: { path: string; value: string } | null } | { why: string };

function abilityProbe(L: string, id: string, base: string, nm: string, ab: Obj, trig: Obj, perms: Map<string, string>, items: Map<string, { base: string; name: string }>): AbilityProbe {
  const type = String(trig.type ?? "");
  const sneaking = type === "sneak_right_click" || (type === "charge_release");
  const ctx = { sneaking, world: "world", items };
  let op = false, time: number | null = null, target: string | null = null;
  for (const c of arr(ab.conditions).filter(isObj)) {
    const r = condOk(c, ctx);
    if (!r.ok) return { why: `it only works when ${r.why ?? "a condition holds"}`.replace("when it ", "when ").replace(/^it only works when it only happens/, "it only happens") };
    if (c.type === "has_permission" && perms.get(String(c.node)) !== "true") op = true;
    if (r.time != null) time = r.time;
    if (r.target) target = r.target;
  }
  const w: Walk = { obs: [], target: false, delayMs: 0, chance: null, untestable: null };
  walkActions(arr(ab.actions), "self", ctx, w);
  if (!w.obs.length) return { why: w.chance != null && w.chance < 1 ? `what it does only happens by chance (${Math.round(w.chance * 100)}%)` : "it has no effect the test player can see or measure" };
  const needTarget = w.target || type === "left_click_hit_entity" || type === "kill_entity" || trig.targetRange != null;
  const tType = target ?? (needTarget ? "husk" : null);
  if (tType && !TARGET_HEALTH[tType]) return { why: "it needs a target the test cannot summon" };
  const pre: ProbeStep[] = [];
  if (time != null) pre.push(S("setup", server(`time set ${time}`), ["Set the time"]));
  pre.push(S("setup", server(`${L} give ${id} {bot}`), ["Gave"]));
  if (tType) pre.push(...targetSteps(tType));
  pre.push(S("setup", { kind: "hold", item: base }));
  const act: ProbeStep[] = [];
  switch (type) {
    case "right_click":
      if (tType) act.push(S("setup", { kind: "look_at", type: tType }));
      act.push(S("act", { kind: "use_item" }));
      break;
    case "sneak_right_click":
      if (tType) act.push(S("setup", { kind: "look_at", type: tType }));
      act.push(S("setup", { kind: "sneak", on: true }), S("act", { kind: "use_item" }));
      break;
    case "left_click_hit_entity": act.push(S("act", { kind: "attack_entity", type: tType ?? "husk" })); break;
    case "kill_entity":
      pre.splice(pre.findIndex((p) => p.role === "setup" && p.step.kind === "server" && String((p.step as { command: string }).command).includes("summon")), 2,
        S("setup", server(`execute at {bot} run summon minecraft:${tType ?? "husk"} ^ ^ ^2 {Tags:["nxo_t"],NoAI:1b,Silent:1b,PersistenceRequired:1b,Health:1f}`), ["Summoned"]));
      act.push(S("setup", { kind: "look_at", type: tType ?? "husk" }), S("act", { kind: "attack_entity", type: tType ?? "husk" }));
      break;
    case "held_interval": {
      const ms = Math.min(9000, Number(trig.periodTicks) * 50 + 800);
      if (!(ms > 0)) return { why: "its interval is not readable" };
      act.push(S("act", { kind: "wait", ms }));
      break;
    }
    case "item_consume":
      pre.unshift(S("setup", server("effect give {bot} minecraft:hunger 4 255 true"), ["Applied"]));
      act.push(S("setup", { kind: "wait", ms: 4200 }), S("act", { kind: "use_item", holdMs: 2200 }));
      break;
    case "charge_release": {
      const ms = Math.min(4000, Math.max(200, Number(trig.minChargeTicks) * 50 + 300));
      act.push(S("setup", { kind: "sneak", on: true }), S("act", { kind: "wait", ms }));
      if (trig.release === "right_click") act.push(S("act", { kind: "use_item" }));
      else act.push(S("act", { kind: "sneak", on: false }));
      break;
    }
    case "join": return { why: "it fires when a player joins, before the test can hold the item" };
    case "death": return { why: "it fires when the player dies (not driven)" };
    case "projectile_hit": return { why: "it fires when a projectile hits something (its launch is tested on its own ability)" };
    case "break_block": return { why: "block-break abilities are not driven yet" };
    default: return { why: `the trigger ${type || "?"} is not driven` };
  }
  if (w.delayMs) act.push(S("setup", { kind: "wait", ms: Math.min(9000, w.delayMs + 300) }));
  const obs = [...w.obs].sort((p, q) => RANK[p.k] - RANK[q.k]);
  const seen = new Set<string>();
  const checks: ProbeStep[] = [];
  let messagePath: { path: string; value: string } | null = null;
  for (const o of obs) {
    if (checks.length >= 3 || seen.has(o.k)) continue;
    seen.add(o.k);
    switch (o.k) {
      case "chat": checks.push(S("check", { kind: "expect_chat", contains: [o.text], withinMs: 2500 })); break;
      case "title": checks.push(S("check", { kind: "expect_title", contains: [o.text], withinMs: 2500 })); break;
      case "effect": checks.push(S("check", { kind: "expect_effect", effect: o.effect, withinMs: 2500 })); break;
      case "item": checks.push(S("check", { kind: "expect_inventory", item: o.item, count: o.item === base ? 2 : 1, ...(o.name ? { name: o.name.slice(0, 100) } : {}), withinMs: 2500 })); break;
      case "damage": if (tType) checks.push(S("probe", server(`execute unless entity @e[tag=nxo_t,nbt={Health:${TARGET_HEALTH[tType].toFixed(1)}f}]`), ["Test passed"])); else seen.delete("damage"); break;
      case "particle": checks.push(S("check", { kind: "expect_particle", particle: o.particle, withinMs: 2000 })); break;
      case "sound": checks.push(S("check", { kind: "expect_sound", sound: o.sound, withinMs: 2000 })); break;
      case "entity": checks.push(S("check", { kind: "expect_entity", type: o.type, withinMs: 1500 })); break;
      case "moved": checks.push(S("check", { kind: "expect_moved", minBlocks: 1, withinMs: 2000 })); break;
    }
  }
  if (!checks.length) return { why: "it has no effect the test player can see or measure" };
  // the first top-level message action is the config_reload candidate (items.<id>.abilities.<ab>.a<i>.text)
  arr(ab.actions).forEach((a, i) => { if (!messagePath && isObj(a) && (a.type === "send_message" || a.type === "actionbar") && (a.to ?? "self") === "self" && literal(String(a.text ?? "")) === obs.find((o) => o.k === "chat")?.["text" as never]) messagePath = { path: `a${i}.text`, value: String(a.text) }; });
  const tail: ProbeStep[] = [];
  if (type === "sneak_right_click" || (type === "charge_release" && trig.release === "right_click")) tail.push(S("cleanup", { kind: "sneak", on: false }));
  if (tType) tail.push(cleanupTargets());
  // a damage check is a console probe: it never stops the scenario, so a visible check (or a final guard) must follow
  if (!checks.some((c) => c.role === "check")) checks.push(S("check", { kind: "expect_no_chat", contains: ["An internal error occurred"], forMs: 300 }));
  return { steps: [...pre, ...act, ...checks, ...tail], op, messagePath };
}

// --------------------------------------------------------------------------------------------- quests
function questSim(L: string, q: Obj, items: Map<string, { base: string; name: string }>, menus: Map<string, Obj>): { steps: ProbeStep[] | null; why?: string } {
  const out: ProbeStep[] = [];
  let pickaxe = false;
  for (const st of arr(q.steps).filter(isObj)) {
    for (const o of arr(st.objectives).filter(isObj)) {
      switch (o.type) {
        case "kill_entity": {
          const n = Number(o.count) || 1;
          if (n > 5) return { steps: null, why: `it needs ${n} kills` };
          const kinds = arr(o.kinds).map(String);
          const t = o.entity ? bare(String(o.entity)) : kinds.includes("player") && kinds.length === 1 ? null : TARGET_FOR[kinds.find((k) => TARGET_FOR[k]) ?? "living"].type;
          if (!t) return { steps: null, why: "it needs player kills" };
          for (let i = 0; i < n; i++) {
            out.push(S("setup", server(`execute at {bot} run summon minecraft:${t} ~2 ~ ~ {Tags:["nxo_k"],NoAI:1b,Silent:1b,Health:1f}`), ["Summoned"]));
            out.push(S("setup", server(`damage @e[tag=nxo_k,limit=1,sort=nearest] 50 minecraft:player_attack by {bot}`), ["Applied"]));
          }
          break;
        }
        case "collect_item": {
          const it = String(o.item), n = Math.max(1, Math.min(2304, Number(o.count) || 1)), d = items.get(it);
          if (o.mode === "pickup") {
            if (d) return { steps: null, why: "it needs a design item picked up from the ground" };
            out.push(S("setup", server(`execute at {bot} run summon minecraft:item ~ ~1 ~ {Item:{id:"${it.includes(":") ? it : `minecraft:${it}`}",count:${Math.min(64, n)}},PickupDelay:0s}`), ["Summoned"]), S("setup", { kind: "wait", ms: 1500 }));
            if (n > 64) return { steps: null, why: `it needs ${n} items picked up` };
          } else {
            out.push(d ? S("setup", server(`${L} give ${it} {bot} ${Math.min(64, n)}`), ["Gave"]) : S("setup", server(`give {bot} ${it.includes(":") ? it : `minecraft:${it}`} ${n}`), ["Gave"]));
            if (d && n > 64) return { steps: null, why: `it needs ${n} design items` };
            out.push(S("setup", { kind: "wait", ms: 2600 }));
          }
          break;
        }
        case "visit_location":
          if (String(o.world) !== "world") return { steps: null, why: `it needs a visit to the world ${String(o.world)}` };
          out.push(S("setup", server(`tp {bot} ${Number(o.x)} ${Number(o.y)} ${Number(o.z)}`), ["Teleported"]), S("setup", { kind: "wait", ms: 2600 }), S("setup", server("tp {bot} 0.5 -60 0.5"), ["Teleported"]));
          break;
        case "break_block": {
          const n = Number(o.count) || 1;
          if (n > 3) return { steps: null, why: `it needs ${n} blocks broken` };
          if (!pickaxe) { out.push(S("setup", server("give {bot} minecraft:netherite_pickaxe"), ["Gave"]), S("setup", { kind: "hold", item: "netherite_pickaxe" })); pickaxe = true; }
          for (let i = 0; i < n; i++) out.push(S("setup", server(`setblock 2 -60 0 ${String(o.block).includes(":") ? String(o.block) : `minecraft:${String(o.block)}`}`), ["Changed the block"]), S("act", { kind: "dig", x: 2, y: -60, z: 0 }));
          break;
        }
        case "talk": {
          const m = menus.get(String(o.menu));
          const ow = m && isObj(m.openWith) ? m.openWith : {};
          if (!m || ow.command === false) return { steps: null, why: "it needs a dialogue opened from an NPC or item" };
          out.push(S("act", { kind: "command", text: `/${L} menu ${String(o.menu)}` }), S("setup", { kind: "wait", ms: 600 }), S("cleanup", { kind: "close_window" }));
          break;
        }
        case "survive": {
          const s = Number(o.seconds) || 0;
          if (s > 8) return { steps: null, why: `it needs ${s} s survived` };
          out.push(S("act", { kind: "wait", ms: Math.min(10000, s * 1000 + 1200) }));
          break;
        }
        case "craft_item": return { steps: null, why: "it needs crafting (not driven yet)" };
        default: return { steps: null, why: `it needs ${String(o.type).replace(/_/g, " ")}` };
      }
    }
  }
  if (out.length > 18) return { steps: null, why: "it needs too many actions for the time budget" };
  return { steps: out };
}

// --------------------------------------------------------------------------------------------- HUDs
function hudProbe(L: string | null, h: Obj, items: Map<string, { base: string; name: string }>): { steps: ProbeStep[]; channel: string; holding: string | null } | { why: string } {
  const chans: [string, Obj | null][] = [["sidebar", isObj(h.sidebar) ? h.sidebar : null], ["boss bar", isObj(h.bossbar) ? h.bossbar : null], ["action bar", isObj(h.actionbar) ? h.actionbar : null]];
  for (const [channel, c] of chans) {
    if (!c) continue;
    const show = isObj(c.show) ? c.show : { when: "always" };
    if (show.when === "in_boss_arena") continue;
    const parts = channel === "sidebar" ? arr(c.title) : arr(c.parts);
    const txt = parts.filter(isObj).map((p) => (p.type === "text" ? String(p.text ?? "") : "")).join(" ");
    const lit = literal(txt, 40) ?? (parts.filter(isObj).some((p) => p.type === "value" && p.format === "percent") ? "%" : null);
    if (!lit) continue;
    const steps: ProbeStep[] = [];
    let holding: string | null = null;
    if (show.when === "holding") {
      const it = items.get(String(show.item));
      if (!it || !L) continue;
      holding = it.name || String(show.item);
      steps.push(S("setup", server(`${L} give ${String(show.item)} {bot}`), ["Gave"]), S("setup", { kind: "hold", item: it.base }));
    }
    steps.push(S("check", channel === "sidebar" ? { kind: "expect_sidebar", contains: [lit], withinMs: 3000 } : channel === "boss bar" ? { kind: "expect_bossbar", contains: [lit], withinMs: 3000 } : { kind: "expect_chat", contains: [lit], withinMs: 3000 }));
    return { steps, channel, holding };
  }
  return { why: "its parts are icons and numbers only (nothing fixed to look for), or it shows only in a boss arena" };
}

// --------------------------------------------------------------------------------------------- misc
function configKeyExists(configYml: string | null, path: string): boolean {
  if (!configYml) return false;
  try { const v = getYamlValue(configYml, path); return v.found && typeof v.value === "string"; } catch { return false; }
}

function hash6(s: string): string {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619) >>> 0; }
  return h.toString(16).padStart(8, "0").slice(0, 6);
}

