}
const SCENARIO_OVERHEAD_MS = 900; // reset (clear + effect clear + 400 ms) and the scenario bookkeeping

const KIND_PRIORITY = ["mod_enables", "menu_opens", "item_given", "ability_effect", "quest_progress", "menu_click", "boss_spawns", "config_reload", "hud_visible", "passive_effect", "recipe_registered", "loot_gives", "advancement_reward", "model_extra"];

export type CompileOptions = { budgetSec?: number; maxScenarios?: number; /** scenario ids already used by a ModSpec playtest in the same flight */ usedScenarioIds?: string[] };

export function compileOracle(exps: Expectation[], opts: CompileOptions = {}): CompiledOracle {
  const budgetMs = Math.max(5, Math.min(120, opts.budgetSec ?? ORACLE_LIMITS.budgetSec)) * 1000;
  const maxSc = Math.max(0, Math.min(ORACLE_LIMITS.scenarios, opts.maxScenarios ?? ORACLE_LIMITS.scenarios));
  const map: Record<string, ExpectationMap> = {};
  const dropped: Record<string, string> = {};
  const rcon: RconCheck[] = [];
  const testable = exps.filter((e) => e.probe && !e.notTestable);
  const needsHostile = testable.some((e) => (e.probe?.bot?.steps ?? []).some((s) => s.step.kind === "server" && /summon minecraft:(husk|zombie|skeleton|spider|creeper)|boss spawn/.test(s.step.command)));

  // ---- RCON (cheap, before the player joins): every console probe, in order, capped
  if (needsHostile) rcon.push({ id: "nxo-setup-1", command: "difficulty easy", required: false });
  for (const e of testable) {
    map[e.id] = { rcon: [], ...(e.probe!.boot ? { boot: e.probe!.boot } : {}) };
    for (const [i, r] of (e.probe!.rcon ?? []).entries()) {
      if (rcon.length >= ORACLE_LIMITS.rconChecks) { dropped[e.id] = "not flown: the oracle's console check limit was reached"; break; }
      const id = `nxo-${e.id.toLowerCase()}-${i + 1}`;
      rcon.push({ ...r.check, id, required: false, expect: undefined, expectNot: undefined });
      map[e.id].rcon.push({ id, role: r.role, ...(r.want ? { want: r.want } : {}), ...(r.wantNot ? { wantNot: r.wantNot } : {}), ...(r.nonEmpty ? { nonEmpty: true } : {}) });
    }
  }
  // config writes go last: the other console checks see the shipped config
  rcon.sort((a, b) => Number(!!a.writeFile) - Number(!!b.writeFile));

  // ---- player scenarios: pick within the budget, one of each kind first
  const own = testable.filter((e) => e.probe!.bot && !e.probe!.bot.attachTo && !dropped[e.id]);
  const prio = (k: string) => { const i = KIND_PRIORITY.indexOf(k); return i < 0 ? 99 : i; };
  const firstOfKind = new Set<string>();
  const order = [...own].sort((a, b) => {
    const fa = firstOfKind.has(a.kind) ? 1 : 0, fb = firstOfKind.has(b.kind) ? 1 : 0;
    return fa - fb || prio(a.kind) - prio(b.kind);
  });
  // stable "one of each kind first": mark the first expectation of every kind
  const seenKind = new Set<string>();
  const firstPass = own.filter((e) => (seenKind.has(e.kind) ? false : (seenKind.add(e.kind), true))).sort((a, b) => prio(a.kind) - prio(b.kind));
  const rest = own.filter((e) => !firstPass.includes(e));
  void order;
  const picked: Expectation[] = [];
  let planned = 0;
  const attachedTo = (host: Expectation) => testable.filter((e) => e.probe!.bot?.attachTo === host.id);
  const cost = (e: Expectation) => SCENARIO_OVERHEAD_MS + [...e.probe!.bot!.steps, ...attachedTo(e).flatMap((x) => x.probe!.bot!.steps)].reduce((a, s) => a + estimateMs(s.step), 0);
  const used = new Set(opts.usedScenarioIds ?? []);
  const free = Math.max(0, Math.min(maxSc, PLAYTEST_LIMITS.scenarios - used.size - 1)); // -1: the closing scenario
  for (const e of [...firstPass, ...rest]) {
    const c = cost(e);
    if (picked.length >= free) { dropped[e.id] = "not flown: the flight's scenario limit was reached"; continue; }
    if (planned + c > budgetMs) { dropped[e.id] = "not flown: the flight's time cap"; continue; }
    picked.push(e); planned += c;
  }
  // fly in derivation order (state such as a teleport stays predictable)
  picked.sort((a, b) => Number(a.id.slice(1)) - Number(b.id.slice(1)));

  const scenarios: PlaytestScenario[] = [];
  let n = ORACLE_SCENARIO_BASE;
  const nextId = () => { while (used.has(`T-${n}`)) n++; return `T-${n++}`; };
  for (const e of picked) {
    const id = nextId();
    const steps: PlaytestStep[] = [];
    const mapped: MappedStep[] = [];
    const summons = e.probe!.bot!.steps.some((s) => s.step.kind === "server" && /tag=nxo_|Tags:\["nxo_/.test(s.step.command));
    if (summons) { steps.push({ kind: "server", command: "kill @e[tag=nxo_t]" }, { kind: "server", command: "kill @e[tag=nxo_k]" }); mapped.push({ role: "cleanup" }, { role: "cleanup" }); }
    const host = e.probe!.bot!.steps;
    // trailing cleanup of the host stays last; attached steps go before it
    let cut = host.length;
    while (cut > 0 && host[cut - 1].role === "cleanup") cut--;
    const add = (list: typeof host) => { for (const s of list) { steps.push(stripExpect(s.step)); mapped.push({ role: s.role, ...(s.want ? { want: s.want } : {}), ...(s.wantNot ? { wantNot: s.wantNot } : {}) }); } };
    const from = steps.length;
    add(host.slice(0, cut));
    map[e.id] = { ...(map[e.id] ?? { rcon: [] }), scenario: id, from, to: steps.length, steps: mapped.slice(from) };
    for (const a of attachedTo(e)) {
      if (dropped[a.id]) continue;
      const f = steps.length;
      add(a.probe!.bot!.steps);
      map[a.id] = { ...(map[a.id] ?? { rcon: [] }), scenario: id, from: f, to: steps.length, steps: mapped.slice(f) };
    }
    add(host.slice(cut));
    if (!steps.some((s) => s.kind.startsWith("expect_"))) { steps.push({ kind: "expect_no_chat", contains: ["An internal error occurred"], forMs: 200 }); mapped.push({ role: "cleanup" }); }
    if (steps.length > PLAYTEST_LIMITS.steps) {
      dropped[e.id] = "not flown: the test has too many steps";
      for (const a of attachedTo(e)) dropped[a.id] = "not flown: its host test has too many steps";
      delete map[e.id].scenario;
      continue;
    }
    scenarios.push({ id, title: e.title.slice(0, 500), steps });
  }
  for (const e of testable) {
    const att = e.probe!.bot?.attachTo;
    if (att && !map[e.id]?.scenario && !dropped[e.id]) dropped[e.id] = picked.some((p) => p.id === att) ? "not flown: its host test was not flown" : "not flown: the test it rides on was not flown";
  }
  if (scenarios.length) {
    const closing: PlaytestStep[] = [{ kind: "server", command: "kill @e[tag=nxo_t]" }, ...(needsHostile ? [{ kind: "server" as const, command: "difficulty peaceful" }] : []), { kind: "expect_no_chat", contains: ["An internal error occurred"], forMs: 100 }];
    scenarios.push({ id: nextId(), title: "oracle cleanup", steps: closing });
  }
  const op = picked.some((e) => e.probe!.bot!.op) || testable.some((e) => e.probe!.bot?.attachTo && e.probe!.bot.op);
  const totalSec = Math.min(PLAYTEST_LIMITS.totalSecMax, Math.ceil(budgetMs / 1000) + 5);
  const plan: PlaytestPlan | null = scenarios.length ? { schema: 1, ...(op ? { op: true } : {}), totalSec, joinSec: ORACLE_LIMITS.joinSec, scenarios } : null;
  return { rcon, plan, map, dropped, timing: { budgetSec: Math.round(budgetMs / 1000), plannedMs: planned, rconChecks: rcon.length, scenarios: scenarios.length } };
}

/** Server steps are judged by the evaluator: never let the bot stop a scenario on them. */
function stripExpect(st: PlaytestStep): PlaytestStep {
  if (st.kind === "server") { const { expect: _e, ...rest } = st; void _e; return rest; }
  return st;
}

/** Fly the oracle in a flight: its console checks after the boot spec's own, its scenarios merged into the playtest. */
export function withOracle(spec: TestFlightSpec, c: CompiledOracle): TestFlightSpec {
  const rconOut = [...(spec.rcon ?? []), ...c.rcon];
  let playtest = spec.playtest;
  if (c.plan) {
    if (!playtest) playtest = c.plan;
    else {
      const scen = [...playtest.scenarios, ...c.plan.scenarios].slice(0, PLAYTEST_LIMITS.scenarios);
      playtest = { ...playtest, op: !!(playtest.op || c.plan.op), totalSec: Math.min(PLAYTEST_LIMITS.totalSecMax, (playtest.totalSec ?? 90) + (c.plan.totalSec ?? 0)), joinSec: Math.max(playtest.joinSec ?? 30, c.plan.joinSec ?? 0), scenarios: scen };
    }
  }
  const out: TestFlightSpec = { ...spec, rcon: rconOut, ...(playtest ? { playtest } : {}) };
  // the bot needs its own time on top of the boot (bounded: the oracle's budget + its join)
  if (c.plan) out.timeouts = { ...(spec.timeouts ?? {}), totalSec: Math.min(900, Math.max(spec.timeouts?.totalSec ?? 420, 300 + (playtest!.totalSec ?? 90) + (playtest!.joinSec ?? 30))) };
  return out;
}

