// Cyrus behaviour oracle (oracle-1): judge every expectation from the flight report. Pure.
// Rules (never relaxed, same spirit as summary.ts / playtest verdict.ts):
// - pass only when every judged step of the expectation ran and matched, with evidence;
// - a setup step that failed = not_run (the test could not be arranged; the mod is not blamed);
// - an act / check / probe step that failed = fail; a step that did not run = not_run;
// - an expectation whose scenario logged a server error while it ran = fail (the mod threw);
// - nothing the oracle did not fly is ever counted; not_testable never counts either way.
import type { TestFlightReport } from "../types";
import type { PlaytestRunResult, ScenarioResult } from "../../playtest/verdict";
import type { CompiledOracle, MappedStep } from "./compile";
import { ORACLE_LIMITS, ORACLE_STAGE, ORACLE_VERSION, type Expectation, type ExpectationResult, type StoredFunctional } from "./types";

const clip = (s: string, n: number = ORACLE_LIMITS.evidenceChars) => String(s).replace(/\s+/g, " ").trim().slice(0, n);
const stripColors = (s: string) => String(s).replace(/§[0-9a-fk-orx]/gi, "");

/** "id 'cmd' [rss 1 MB, 2 ms]: ok -> reply" -> { state, reply } (null = the check never ran). */
export function rconLine(lines: string[], id: string): { state: "ok" | "failed" | "error"; reply: string; line: string } | null {
  const l = lines.find((x) => x.startsWith(`${id} '`));
  if (!l) return null;
  if (/': ERROR /.test(l)) return { state: "error", reply: l.replace(/^.*?': ERROR /, ""), line: l };
  const m = /\]: (ok|FAILED)(.*?)(?: -> (.*))?$/.exec(l);
  if (!m) return { state: "error", reply: l, line: l };
  return { state: m[1] === "ok" ? "ok" : "failed", reply: m[3] ?? "", line: l };
}

/** The console reply of a playtest `server` step (bot.js: "console 'cmd' -> reply"). */
export function serverReply(ev: string[]): string {
  const l = ev.find((x) => x.startsWith("console '")) ?? "";
  const i = l.indexOf("' -> ");
  return i >= 0 ? l.slice(i + 5) : "";
}

function matches(reply: string, m: MappedStep): { ok: boolean; why: string | null } {
  const r = stripColors(reply);
  if (m.nonEmpty && !r.trim().replace(/^\(empty\)$/, "")) return { ok: false, why: "it answered nothing" };
  const miss = (m.want ?? []).filter((w) => !r.toLowerCase().includes(w.toLowerCase()));
  if (miss.length) return { ok: false, why: `the reply lacks ${JSON.stringify(miss)}` };
  const bad = (m.wantNot ?? []).filter((w) => r.includes(w));
  if (bad.length) return { ok: false, why: `the reply says ${JSON.stringify(bad[0])}` };
  return { ok: true, why: null };
}

type Verdict = { status: ExpectationResult["status"]; reason: string | null; evidence: string[] };
const pass = (evidence: string[]): Verdict => ({ status: "pass", reason: null, evidence });
const notRun = (reason: string, evidence: string[] = []): Verdict => ({ status: "not_run", reason, evidence });
const fail = (reason: string, evidence: string[] = []): Verdict => ({ status: "fail", reason, evidence });

/** Judge one step outcome by its role. null = fine, carry on. */
function byRole(role: MappedStep["role"], ok: boolean | null, why: string, ev: string[]): Verdict | null {
  if (role === "cleanup") return null;
  if (ok === null) return notRun(why, ev);
  if (ok) return null;
  return role === "setup" ? notRun(`the test could not be set up: ${why}`, ev) : fail(why, ev);
}

export type EvaluateOptions = { pluginName: string; version: string; now?: () => Date };

export function evaluateOracle(exps: Expectation[], c: CompiledOracle | null, report: TestFlightReport | null, o: EvaluateOptions): StoredFunctional {
  const at = (o.now ?? (() => new Date()))().toISOString();
  const completed = !!report && report.status === "completed";
  const rconEv = report?.checks.find((x) => x.id === "rcon_checks")?.evidence ?? [];
  const peEv = report?.checks.find((x) => x.id === "plugins_enabled")?.evidence ?? [];
  const run = (report?.playtest ?? null) as PlaytestRunResult | null;
  const scen = new Map<string, ScenarioResult>((run?.scenarios ?? []).map((s) => [s.id, s]));
  const botWhy = !run ? "the test player did not run" : !run.joined ? `the test player could not join (${clip((run.notes ?? []).slice(-1)[0] ?? "no detail", 160)})` : null;

  const results: ExpectationResult[] = exps.slice(0, ORACLE_LIMITS.expectations).map((e) => {
    const base = { id: e.id, kind: e.kind, title: e.title, source: `${e.source.from}:${e.source.ref}`.slice(0, 120), origin: e.origin };
    let v: Verdict;
    try { v = judge(e); } catch (err) { v = notRun(`oracle error: ${clip((err as Error).message, 160)}`); }
    return { ...base, status: v.status, reason: v.reason ? clip(v.reason, 300) : null, evidence: v.evidence.slice(0, ORACLE_LIMITS.evidence).map((x) => clip(x)) };
  });

  function judge(e: Expectation): Verdict {
    if (e.notTestable || !e.probe) return { status: "not_testable", reason: e.notTestable ?? "no probe", evidence: [] };
    if (!c) return notRun("the oracle did not fly");
    if (c.dropped[e.id]) return notRun(c.dropped[e.id]);
    if (!completed) return notRun(report ? `the flight did not complete (${report.status})` : "the flight did not run");
    const m = c.map[e.id];
    if (!m) return notRun("not flown");
    const ev: string[] = [];
    if (m.boot === "plugins_enabled") {
      const line = peEv.find((l) => l.startsWith(`${o.pluginName}: `));
      if (!line) return notRun("the plugin check did not run");
      return /^[^:]+: enabled/.test(line) ? pass([line]) : fail("the mod did not start (Paper did not enable it)", [line]);
    }
    for (const r of m.rcon) {
      const l = rconLine(rconEv, r.id);
      if (!l) { const v = byRole(r.role, null, "the console check did not run", []); if (v) return v; continue; }
      const ok = l.state === "error" ? false : matches(l.reply, r);
      const why = l.state === "error" ? `the console check failed: ${l.reply}` : (ok as { why: string | null }).why ?? "";
      const v = byRole(r.role, l.state === "error" ? (r.role === "setup" ? false : false) : (ok as { ok: boolean }).ok, why, [l.line]);
      if (v) return v;
      if (r.role !== "cleanup") ev.push(`console: ${l.line.replace(/ \[rss [^\]]*\]/, "")}`);
    }
    if (m.scenario) {
      if (botWhy) return notRun(botWhy, ev);
      const sc = scen.get(m.scenario);
      if (!sc) return notRun("its scenario did not run", ev);
      const steps = sc.steps ?? [];
      // an earlier part of a shared scenario (the host of an attached check) must have passed
      for (let i = 0; i < (m.from ?? 0); i++) if (steps[i] && steps[i].status !== "pass") return notRun("the test it rides on did not pass", ev);
      for (let i = m.from ?? 0, k = 0; i < (m.to ?? 0); i++, k++) {
        const ms = m.steps![k], st = steps[i];
        if (!st) { const v = byRole(ms.role, null, "the step did not run", ev); if (v) return v; continue; }
        const stEv = (st.evidence ?? []).map(String);
        if (st.status === "not_run") { const v = byRole(ms.role, null, clip(stEv[0] ?? "the step did not run", 200), ev); if (v) return v; continue; }
        let ok = st.status === "pass" && stEv.some((x) => x.trim());
        let why = clip(stEv.join("; ") || st.kind, 220);
        if (ok && st.kind === "server" && (ms.want || ms.wantNot || ms.nonEmpty)) { const r = matches(serverReply(stEv), ms); ok = r.ok; if (!r.ok) why = `${r.why}: ${clip(stEv[0] ?? "", 200)}`; }
        const v = byRole(ms.role, ok, why, [...ev, ...stEv.slice(0, 2)]);
        if (v) return v;
        if (ms.role === "check" || ms.role === "probe" || ms.role === "act") ev.push(clip(stEv[0] ?? st.kind));
      }
      if (sc.failedBy === "server_log" || (sc.logHits ?? []).length) return fail(`the server logged an error while it ran: ${clip((sc.logHits ?? [])[0] ?? "", 200)}`, ev);
    }
    if (!ev.length) return notRun("no evidence was recorded");
    return pass(ev.slice(-ORACLE_LIMITS.evidence));
  }

  return summarizeFunctional(results, { version: o.version, at, timing: c?.timing, reason: !c ? "the oracle did not fly" : !completed ? (report ? `the flight did not complete (${report.status})` : "the flight did not run") : undefined });
}

/** Counts, score, verdict and the owner line from per-expectation results (also used for not_run records). */
export function summarizeFunctional(results: ExpectationResult[], o: { version: string; at: string; timing?: StoredFunctional["timing"]; reason?: string }): StoredFunctional {
  const n = (s: string) => results.filter((r) => r.status === s).length;
  const passed = n("pass"), failed = n("fail"), notRunN = n("not_run"), notTestable = n("not_testable");
  const total = results.length, ran = passed + failed;
  const verdict: StoredFunctional["verdict"] = failed ? "failed" : passed ? "passed" : "not_run";
  const score = ran ? Math.round((passed / ran) * 1000) / 1000 : null;
  const coverage = total ? Math.round((ran / total) * 1000) / 1000 : null;
  const label = !ran
    ? `Behaviour not tested${o.reason ? `: ${o.reason}` : notRunN || notTestable ? `: none of the ${total} checks could run` : ""}`
    : `We tried ${ran} of the ${total} things this mod should do on a real Paper ${o.version} server: ${passed} worked${failed ? `, ${failed} did not` : ""}.`;
  return {
    schema: 1, oracle: ORACLE_VERSION, stage: ORACLE_STAGE, state: ran || !o.reason ? "done" : "not_run", verdict, score, coverage,
    counts: { total, passed, failed, notRun: notRunN, notTestable }, label, ...(o.reason ? { reason: o.reason } : {}), expectations: results,
    ...(o.timing ? { timing: o.timing } : {}), at: o.at,
  };
}

/** A not_run record (switched off for a reason, an oracle error, nothing derived). Never a pass. */
export function functionalNotRun(reason: string, o: { version: string; now?: () => Date; expectations?: Expectation[] }): StoredFunctional {
  const at = (o.now ?? (() => new Date()))().toISOString();
  const results: ExpectationResult[] = (o.expectations ?? []).slice(0, ORACLE_LIMITS.expectations).map((e) => ({ id: e.id, kind: e.kind, title: e.title, source: `${e.source.from}:${e.source.ref}`.slice(0, 120), origin: e.origin, status: e.notTestable ? "not_testable" : "not_run", reason: e.notTestable ?? reason, evidence: [] }));
  return { ...summarizeFunctional(results, { version: o.version, at, reason }), state: "not_run" };
}

/** Read a stored functional record back (tolerant). */
export function readFunctional(raw: unknown): StoredFunctional | null {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
  const r = raw as StoredFunctional;
  return r.schema === 1 && r.stage === ORACLE_STAGE && Array.isArray(r.expectations) && r.counts && typeof r.counts.total === "number" ? r : null;
}

