// Cyrus behaviour oracle (oracle-1): read the oracle's inputs (SERVER ONLY: unzips jars with node:zlib).
// plugin.yml + config.yml come from the built jar; designer / data pack / creature specs from the build-service record
// (eval, scripts) or from the portal's stored project assets (the gate). Nothing here calls a model.
import { DEFAULT_ZIP_LIMITS, indexZip, readEntry } from "../../inventory/zipread";
import type { OracleInput } from "./types";

/** plugin.yml and config.yml of a jar (null when absent or unreadable). */
export function jarTexts(jar: Buffer | null): { pluginYml: string | null; configYml: string | null } {
  if (!jar) return { pluginYml: null, configYml: null };
  const idx = indexZip(jar, DEFAULT_ZIP_LIMITS);
  if (!idx.ok) return { pluginYml: null, configYml: null };
  const read = (name: string) => {
    const e = idx.zip.entries.find((x) => !x.dir && x.name === name);
    if (!e) return null;
    const r = readEntry(idx.zip, e, 512 * 1024);
    return r.ok ? r.data.toString("utf8") : null;
  };
  return { pluginYml: read("plugin.yml"), configYml: read("config.yml") };
}

type Obj = Record<string, unknown>;
const isObj = (v: unknown): v is Obj => !!v && typeof v === "object" && !Array.isArray(v);
const arr = (v: unknown): Obj[] => (Array.isArray(v) ? v.filter(isObj) : []);

/**
 * Inputs from a build-service record (GET /builds/:id): assetResult.designs / datapacks / creatures carry the specs.
 * `datapacksFlown` = names of the data packs that are part of the flight (an eval flight carries none: no data pack
 * expectations then). `engines` = plugins the flight adds (e.g. BetterModel).
 */
export function inputFromServiceRecord(rec: { pluginName?: string | null; assetResult?: unknown }, jar: Buffer | null, version: string, o: { datapacksFlown?: string[]; engines?: string[] } = {}): OracleInput {
  const ar = isObj(rec.assetResult) ? rec.assetResult : {};
  const t = jarTexts(jar);
  const flown = new Set(o.datapacksFlown ?? []);
  return {
    version, pluginName: String(rec.pluginName ?? ""), namespace: typeof ar.namespace === "string" ? ar.namespace : null,
    pluginYml: t.pluginYml, configYml: t.configYml,
    designs: arr(ar.designs).filter((d) => isObj(d.spec)).map((d) => ({ name: String(d.name ?? ""), spec: d.spec })),
    datapacks: arr(ar.datapacks).filter((d) => isObj(d.spec) && flown.has(String(d.name))).map((d) => ({ name: String(d.name), spec: d.spec })),
    creatures: arr(ar.creatures).map((c) => ({ name: String(c.name ?? ""), key: typeof c.key === "string" ? c.key : null })),
    engines: o.engines ?? [],
  };
}

/** Inputs from the portal's stored assets (CyrusProjectAsset rows of the build's revision). */
export function inputFromStoredAssets(a: { pluginName: string; version: string; namespace: string | null; jar: Buffer | null; designs: { assetKey: string; provenance: unknown }[]; datapacks: { name: string; spec: unknown }[]; creatures: { name: string; key?: string | null }[]; engines?: string[] }): OracleInput {
  const t = jarTexts(a.jar);
  return {
    version: a.version, pluginName: a.pluginName, namespace: a.namespace, pluginYml: t.pluginYml, configYml: t.configYml,
    designs: a.designs.map((d) => ({ name: d.assetKey, spec: isObj(d.provenance) ? d.provenance.spec : null })).filter((d) => isObj(d.spec)),
    datapacks: a.datapacks, creatures: a.creatures, engines: a.engines ?? [],
  };
}

