// Cyrus behaviour oracle (oracle-1): plan the oracle into a flight and judge it afterwards. Pure.
// Failure isolation: anything that goes wrong here (a derivation bug, a probe the validator refuses) returns a
// not_run record and the ORIGINAL flight spec, so the plugin's own Test Flight is never changed by an oracle problem.
import { validateSpec } from "../spec";
import type { TestFlightReport, TestFlightSpec } from "../types";
import { compileOracle, withOracle, type CompiledOracle } from "./compile";
import { deriveExpectations } from "./derive";
import { evaluateOracle, functionalNotRun } from "./evaluate";
import { ORACLE_FLAG, ORACLE_LIMITS, type Expectation, type OracleInput, type StoredFunctional } from "./types";
import { playtestVersion } from "../../playtest/plan";

export const oracleEnabled = (env: Record<string, string | undefined> = process.env) => env[ORACLE_FLAG] === "1";

export type OraclePlan =
  | { ok: true; spec: TestFlightSpec; expectations: Expectation[]; compiled: CompiledOracle }
  | { ok: false; spec: TestFlightSpec; expectations: Expectation[]; record: StoredFunctional };

/** Add the oracle to a flight spec, or explain why not (the spec comes back unchanged). */
export function planOracle(input: OracleInput, spec: TestFlightSpec, o: { env?: Record<string, string | undefined>; budgetSec?: number; now?: () => Date } = {}): OraclePlan {
  let expectations: Expectation[] = [];
  const nr = (reason: string): OraclePlan => ({ ok: false, spec, expectations, record: functionalNotRun(reason, { version: spec.version, now: o.now, expectations }) });
  try {
    expectations = deriveExpectations(input, { env: o.env });
    if (!expectations.length) return nr("nothing to check was found in this build");
    const pv = playtestVersion(spec.version);
    // without a verified test player on this version only the console checks can fly
    const usable = pv.ok ? expectations : expectations.map((e) => (e.probe?.bot ? { ...e, probe: e.probe.rcon?.length ? { ...e.probe, bot: undefined } : null, ...(e.probe.rcon?.length ? {} : { notTestable: `the test player is not verified on Minecraft ${spec.version}` }) } : e));
    const compiled = compileOracle(usable, { budgetSec: o.budgetSec ?? ORACLE_LIMITS.budgetSec, usedScenarioIds: (spec.playtest?.scenarios ?? []).map((s) => s.id) });
    const flown = withOracle(spec, compiled);
    const v = validateSpec(flown);
    if (!v.ok) return nr(`oracle error: its probes were refused (${v.errors[0] ?? "invalid"})`.slice(0, 300));
    return { ok: true, spec: flown, expectations: usable, compiled };
  } catch (e) {
    return nr(`oracle error: ${(e as Error).message}`.slice(0, 300));
  }
}

/** Judge a flown oracle. Never throws: an evaluator bug is a not_run record. */
export function judgeOracle(p: OraclePlan, report: TestFlightReport | null, o: { pluginName: string; version: string; now?: () => Date }): StoredFunctional {
  if (!p.ok) return p.record;
  try { return evaluateOracle(p.expectations, p.compiled, report, o); }
  catch (e) { return functionalNotRun(`oracle error: ${(e as Error).message}`.slice(0, 300), { version: o.version, now: o.now, expectations: p.expectations }); }
}

