('''export function statsText(s: JournalStats, title = "eval journal"): string {''','''export function behaviourStats(rows: StatRow[]): JournalStats["behaviour"] {
  const ran = rows.filter((r) => r.behaviour === "pass" || r.behaviour === "fail");
  const behaved = ran.filter((r) => r.behaviour === "pass").length;
  const k = new Map<string, { pass: number; fail: number; notRun: number; notTestable: number }>();
