"use strict";
// FAKE mineflayer for test/cyrus-playtest.test.ts: simulates the TfPlay fixture plugin in memory so bot.js step logic
// can be tested without a server. FAKE_BROKEN=1 makes /tfgem give dirt (like the play-broken fixture).
// FAKE_KICK=1 kicks the bot at login.
const { EventEmitter } = require("events");
class V { constructor(x, y, z) { this.x = x; this.y = y; this.z = z; } clone() { return new V(this.x, this.y, this.z); } distanceTo(o) { return Math.hypot(this.x - o.x, this.y - o.y, this.z - o.z); } }
exports.createBot = (opts) => {
  const bot = new EventEmitter();
  const items = [];
  bot.username = opts.username;
  bot.entity = { position: new V(0.5, 4, 0.5), effects: {} };
  bot.registry = { effects: { 1: { name: "Speed" } } };
  bot.inventory = { items: () => items.slice() };
  bot.heldItem = null;
  const say = (t) => bot.emit("messagestr", t, "system");
  bot.chat = (t) => setTimeout(() => {
    if (t === "/tfgem") {
      const broken = process.env.FAKE_BROKEN === "1";
      items.push({ name: broken ? "dirt" : "diamond", count: 1, customName: JSON.stringify({ text: "Cyrus Gem" }) });
      say("Here is your Cyrus Gem");
    } else if (t === "/tfboost") { bot.entity.effects[1] = { id: 1, amplifier: 1, duration: 600 }; bot.emit("title", JSON.stringify({ text: "BOOST" }), "title"); say("Boosted!"); }
    else if (t === "/tfup") { bot.entity.position = new V(0.5, 12, 0.5); bot.emit("move"); say("Up you go"); }
    else say(`Unknown command: ${t}`);
  }, 30);
  bot.equip = async (it) => { bot.heldItem = it; };
  bot.activateItem = () => { if (bot.heldItem && bot.heldItem.name === "diamond") setTimeout(() => say("The Cyrus Gem glows"), 20); };
  bot.deactivateItem = () => {};
  bot.quit = () => setTimeout(() => bot.emit("end", "quit"), 5);
  setTimeout(() => {
    if (process.env.FAKE_KICK === "1") { bot.emit("kicked", JSON.stringify({ text: "You are not welcome" })); bot.emit("end", "kicked"); return; }
    say(`Welcome to TfPlay, ${opts.username}`);
    bot.emit("spawn");
  }, 30);
  return bot;
};

