"use strict";
// FAKE mineflayer for test/cyrus-oracle.test.ts: a tiny in-memory "designer mod" so the bot.js steps the behaviour
// oracle added (look_at, attack_entity, click_window, close_window, use_item holdMs, expect_window / particle / sound /
// bossbar / sidebar, the action bar packet) can be tested without a server.
//   /nxo menu shop      opens "Shop" (slot 10: stone "Buy Stone", slot 12: bread "Buy Bread")
//   click slot 10       gives 16 stone + "Bought 16 Stone."
//   right-click (wand)  flame particles + sound nx:wand.zap + action bar "Zap!" ; a husk stands 3 blocks away
//   /nxo boss           a boss bar "The Hollow King" ; /nxo hud: sidebar "Quests" / "Kill 3 zombies"
// FAKE_MUTANT=<name> breaks exactly one of them: title | slot | click | particle | sound | bossbar | sidebar | actionbar | attack.
const { EventEmitter } = require("events");
class V {
  constructor(x, y, z) { this.x = x; this.y = y; this.z = z; }
  clone() { return new V(this.x, this.y, this.z); }
  offset(a, b, c) { return new V(this.x + a, this.y + b, this.z + c); }
  distanceTo(o) { return Math.hypot(this.x - o.x, this.y - o.y, this.z - o.z); }
}
const M = process.env.FAKE_MUTANT || "";
exports.createBot = (opts) => {
  const bot = new EventEmitter();
  const client = new EventEmitter();
  bot._client = client;
  const items = [];
  bot.username = opts.username;
  bot.entity = { position: new V(0.5, -60, 0.5), effects: {} };
  bot.registry = { effects: {} };
  bot.inventory = { items: () => items.slice() };
  bot.heldItem = null;
  bot.currentWindow = null;
  bot.bossBars = [];
  bot.scoreboard = {};
  const husk = { name: "husk", position: new V(3.5, -60, 0.5), height: 1.95, hits: 0 };
  bot.entities = { 1: bot.entity, 2: husk };
  const say = (t) => bot.emit("messagestr", t, "system");
  bot.chat = (t) => setTimeout(() => {
    if (t === "/nxo menu shop") {
      const slots = [];
      slots[10] = { slot: 10, name: M === "slot" ? "dirt" : "stone", count: 1, customName: JSON.stringify({ text: "Buy Stone" }) };
      slots[12] = { slot: 12, name: "bread", count: 1, customName: JSON.stringify({ text: "Buy Bread" }) };
      for (let i = 0; i < 27; i++) if (!slots[i]) slots[i] = { slot: i, name: "gray_stained_glass_pane", count: 1 };
      bot.currentWindow = { title: JSON.stringify({ text: M === "title" ? "Store" : "Shop" }), inventoryStart: 27, slots };
      bot.emit("windowOpen", bot.currentWindow);
    } else if (t === "/nxo boss") bot.bossBars = [{ title: { toString: () => (M === "bossbar" ? "Boss" : "The Hollow King") } }];
    else if (t === "/nxo hud") bot.scoreboard = { sidebar: { title: M === "sidebar" ? "Board" : "Quests", items: [{ name: "Kill 3 zombies" }] } };
    else if (t === "/nxo wand") items.push({ name: "blaze_rod", count: 1, customName: JSON.stringify({ text: "Zap Wand" }) });
    else say(`Unknown command: ${t}`);
  }, 30);
  bot.clickWindow = async (slot) => {
    if (bot.currentWindow && slot === 10 && M !== "click") { items.push({ name: "stone", count: 16 }); say("Bought 16 Stone."); }
  };
  bot.closeWindow = () => { bot.currentWindow = null; };
  bot.equip = async (it) => { bot.heldItem = it; };
  bot.lookAt = async () => {};
  bot.attack = (e) => { if (M !== "attack") e.hits++; if (e.hits) say(`You hit the ${e.name}`); };
  bot.activateItem = () => {
    if (!bot.heldItem || bot.heldItem.name !== "blaze_rod") return;
    setTimeout(() => {
      if (M !== "particle") bot.emit("particle", { id: 1, name: "flame" });
      bot.emit("particle", { id: 2, name: "smoke" });
      if (M !== "sound") bot.emit("soundEffectHeard", "nx:wand.zap");
      if (M !== "actionbar") client.emit("action_bar", { text: JSON.stringify({ text: "Zap!" }) });
    }, 20);
  };
  bot.deactivateItem = () => {};
  bot.quit = () => setTimeout(() => bot.emit("end", "quit"), 5);
  setTimeout(() => { say(`Welcome, ${opts.username}`); bot.emit("spawn"); }, 30);
  return bot;
};

