// Cyrus behaviour oracle (oracle-1): pure tests. "Suspect the oracle": every expectation kind has a GOLDEN (the
// evidence a working mod produces -> pass) and a MUTANT (one defect -> fail, or the right not_run), so a green result
// can never come from a checker that cannot fail. Also: derivation on the real owner-batch builds, determinism, the
// compiled plan passing BOTH validators (TS and the runner's JS), the time cap, failure isolation, the gate wiring and
// the new bot.js steps against a fake mineflayer.
// Run: tsx --test test/cyrus-oracle.test.ts (devhost test). Real flights: scripts/cyrus/oracle-flight.ts (node-2).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { deriveExpectations, commandsOf, giveArgOf, literal } from "../lib/cyrus/testflight/oracle/derive";
import { compileOracle, withOracle, type CompiledOracle } from "../lib/cyrus/testflight/oracle/compile";
import { evaluateOracle, rconLine, readFunctional } from "../lib/cyrus/testflight/oracle/evaluate";
import { planOracle, judgeOracle } from "../lib/cyrus/testflight/oracle/run";
import { verifiedPanel } from "../lib/cyrus/testflight/oracle/view";
import { EXPECTATION_KINDS, type Expectation, type ExpectationKind, type OracleInput } from "../lib/cyrus/testflight/oracle/types";
import { validatePlaytestPlan, type PlaytestPlan, type PlaytestStep } from "../lib/cyrus/playtest/plan";
import { validateSpec } from "../lib/cyrus/testflight/spec";
import type { TestFlightReport, TestFlightSpec } from "../lib/cyrus/testflight/types";
import type { ScenarioResult } from "../lib/cyrus/playtest/verdict";
import { flyOne, type GateDeps } from "../lib/cyrus/testflight/gate-worker";
import { scoreBuild } from "../lib/cyrus/eval/score";
import { behaviourStats } from "../lib/cyrus/eval/stats";
// eslint-disable-next-line @typescript-eslint/no-require-imports
const PT = require("../services/modbuilder/tools/testflight/playtest-lib.js");

const FIX = path.join(__dirname, "fixtures", "cyrus-oracle");
const real = (k: string): OracleInput => JSON.parse(readFileSync(path.join(FIX, "builds", `${k}.json`), "utf8"));

// ------------------------------------------------------------------------------------------- a kitchen-sink mod
const NS = "nx_testtest";
const PLUGIN_YML = `name: Kitchen
version: '1.0.0'
main: dev.nxeon.plugins.kitchen.Kitchen
api-version: '1.21.11'
commands:
  kitchen:
    description: 'Kitchen: menus, quests and items'
    usage: '/kitchen <menu|quests|give|list|params|reload|boss|hud>'
permissions:
  ${NS}.give:
    default: op
`;
const CONFIG_YML = `config_version: 1
menus:
  shop:
    # menu title (text, max 32 characters)
    title: "Shop"
items:
  wand:
    abilities:
      zap:
        a0:
          text: "Zap!"
bosses:
  king:
    name: "The King"
`;
const DESIGNS = [
  { name: "wand", spec: { schemaVersion: 1, id: "wand", base: "minecraft:blaze_rod", name: { text: "Zap Wand" }, abilities: [
    { id: "zap", name: "Zap", trigger: { type: "right_click" }, actions: [{ type: "actionbar", text: "Zap!" }, { type: "spawn_particles", particle: "flame", count: 8 }] },
    { id: "boost", name: "Boost", trigger: { type: "sneak_right_click" }, actions: [{ type: "potion_effect", effect: "speed", durationTicks: 100 }] },
    { id: "smite", name: "Smite", trigger: { type: "left_click_hit_entity" }, actions: [{ type: "damage", amount: 4 }] },
  ], passives: [{ effect: "night_vision", slot: "main_hand" }], recipe: { kind: "shapeless", ingredients: ["minecraft:stick"] } } },
  { name: "lucky", spec: { schemaVersion: 1, id: "lucky", base: "minecraft:gold_nugget", name: { text: "Lucky" }, abilities: [
    { id: "gamble", name: "Gamble", trigger: { type: "right_click" }, actions: [{ type: "branch", if: [{ type: "random_chance", chance: 0.3 }], then: [{ type: "send_message", text: "Jackpot" }] }] },
  ] } },
  { name: "shop", spec: { schemaVersion: 1, kind: "menu", id: "shop", title: "Shop", style: "chest", rows: 3, buttons: [
    { slot: 10, icon: { material: "minecraft:stone", name: { text: "Buy Stone" } }, actions: [{ type: "give_item", item: "minecraft:stone", count: 16 }, { type: "send_message", text: "Bought 16 Stone." }], cost: { type: "item", item: "minecraft:emerald", count: 1 } },
    { slot: 12, icon: { material: "minecraft:paper", name: { text: "Hello" } }, actions: [{ type: "send_message", text: "Hello there" }] },
  ] } },
  { name: "hunt", spec: { schemaVersion: 1, kind: "quest", id: "hunt", title: "Hunt", steps: [{ id: "s1", text: "Kill a pig", objectives: [{ type: "kill_entity", entity: "minecraft:pig", count: 2 }] }], rewards: [{ type: "give_item", item: "minecraft:diamond", count: 1 }] } },
  { name: "king", spec: { schemaVersion: 1, kind: "boss", id: "king", name: { text: "The King" }, entity: "minecraft:wither_skeleton", bossBar: { color: "purple" }, spawn: { command: true } } },
  { name: "hud", spec: { schemaVersion: 1, kind: "hud", id: "hud", sidebar: { title: [{ type: "text", text: "Quests" }], lines: [[{ type: "text", text: "go" }]] } } },
];
const DATAPACK = { name: "dp", spec: { schemaVersion: 1, name: "dp", resources: [
  { type: "recipe", id: "saddle", recipe: { kind: "shapeless", ingredients: ["minecraft:leather"], result: { item: "minecraft:saddle" } } },
  { type: "loot_table", id: "chests/bonus", table: { kind: "chest", pools: [] } },
  { type: "advancement", id: "first", advancement: { display: { title: "First" }, rewards: { experience: 50 } } },
] } };
const KITCHEN: OracleInput = { version: "1.21.11", pluginName: "Kitchen", namespace: NS, pluginYml: PLUGIN_YML, configYml: CONFIG_YML, designs: DESIGNS, datapacks: [DATAPACK], creatures: [{ name: "goblin" }] };
const PLAIN: OracleInput = { version: "1.21.11", pluginName: "Plain", namespace: NS, configYml: null, pluginYml: `name: Plain
version: 1.0.0
main: a.B
commands:
  plain:
    description: Give or reload.
    usage: /plain give <helmet|boots> [player] | /plain reload
    permission: plain.admin
permissions:
  plain.admin:
    default: op
` };

// ------------------------------------------------------------------------------------------- a simulated runner
/** What a WORKING mod's flight reports for a compiled oracle (every step passes, every console reply matches). */
type Over = { rcon?: Record<string, string | null>; step?: Record<string, { status?: "pass" | "fail" | "not_run"; reply?: string; ev?: string }>; logHit?: string; enabled?: boolean; joined?: boolean; status?: TestFlightReport["status"] };
function simulate(c: CompiledOracle, o: Over = {}): TestFlightReport {
  const rconEv = c.rcon.map((r) => {
    const reply = o.rcon && r.id! in o.rcon ? o.rcon[r.id!] : goodReply(c, r.id!);
    return reply === null ? `${r.id} '${r.command}': ERROR rcon timeout after 10000 ms` : `${r.id} '${r.command}' [rss 900 MB, 4 ms]: ok (optional) -> ${reply}`;
  });
  const scenarios: ScenarioResult[] = (c.plan?.scenarios ?? []).map((sc) => {
    let stopped = false;
    const steps = sc.steps.map((st, i) => {
      const key = `${sc.id}#${i}`, ov = o.step?.[key];
      if (stopped) return { i, kind: st.kind, status: "not_run" as const, evidence: ["skipped: an earlier step did not pass"], ms: 0 };
      const status = ov?.status ?? "pass";
      const ev = st.kind === "server" ? [`console '${st.command}' -> ${ov?.reply ?? goodStepReply(c, sc.id, i)}`] : [ov?.ev ?? `${st.kind} ok`];
      if (status !== "pass") stopped = true;
      return { i, kind: st.kind, status, evidence: ev, ms: 5 };
    });
    const hit = o.logHit === sc.id;
    return { id: sc.id, title: sc.title ?? null, covers: [], status: steps.some((s) => s.status === "fail") || hit ? "fail" : steps.every((s) => s.status === "pass") ? "pass" : "not_run", steps, ms: 50, ...(hit ? { logHits: ["L99 [exception] java.lang.NullPointerException at dev.nxeon.X"], failedBy: "server_log" as const } : {}) };
  });
  return {
    schema: 1, runId: "tf-test", status: o.status ?? "completed", version: "1.21.11", javaRelease: 21, startedAt: "", finishedAt: "",
    checks: [
      { id: "plugins_enabled", status: o.enabled === false ? "fail" : "pass", required: true, durationMs: 1, evidence: [o.enabled === false ? "Kitchen: NOT enabled (log: enabling=true enableError=true)" : "Kitchen: enabled (log: enabling=true)", "Plain: enabled (log: enabling=true)"] },
      { id: "rcon_checks", status: "pass", required: true, durationMs: 1, evidence: rconEv },
    ],
    timings: {}, bootMs: 1, doneReportedSec: 1, peakRssKb: 1, artifacts: [], engine: null, notes: [], overall: "passed",
    playtest: { schema: 1, username: "NxPlaytest", version: "1.21.11", joined: o.joined !== false, joinFailed: false, joinMs: 10, op: true, bot: { mineflayer: "4.39.0", minecraftProtocol: null, lockSha256: null }, scenarios: o.joined === false ? [] : scenarios, notes: o.joined === false ? ["bot did not spawn within 15000 ms"] : [], disconnect: null },
  } as TestFlightReport;
}
function mappedFor(c: CompiledOracle, pred: (m: CompiledOracle["map"][string]) => boolean) { return Object.values(c.map).find(pred); }
function goodReply(c: CompiledOracle, id: string): string {
  const m = Object.values(c.map).flatMap((x) => x.rcon).find((r) => r.id === id);
  return m?.want?.length ? m.want.join(" ") : "Kitchen: ok";
}
function goodStepReply(c: CompiledOracle, sc: string, i: number): string {
  const m = mappedFor(c, (x) => x.scenario === sc && i >= (x.from ?? 0) && i < (x.to ?? 0));
  const s = m?.steps?.[i - (m.from ?? 0)];
  return s?.want?.length ? s.want.join(" ") : "done";
}
/** The step keys (scenario#index) and rcon ids of one expectation, with their roles. */
function partsOf(c: CompiledOracle, id: string) {
  const m = c.map[id];
  const steps = m?.scenario ? (m.steps ?? []).map((s, k) => ({ key: `${m.scenario}#${(m.from ?? 0) + k}`, ...s })) : [];
  return { rcon: m?.rcon ?? [], steps };
}

const kitchen = () => { const exps = deriveExpectations(KITCHEN, { env: {} }); return { exps, c: compileOracle(exps, { budgetSec: 120 }) }; };
const judge = (exps: Expectation[], c: CompiledOracle, r: TestFlightReport) => evaluateOracle(exps, c, r, { pluginName: "Kitchen", version: "1.21.11", now: () => new Date(0) });
const statusOf = (f: ReturnType<typeof judge>, id: string) => f.expectations.find((e) => e.id === id)!.status;

