    assert.ok(c.plan!.scenarios.every((s) => /^T-9\d\d$/.test(s.id)));
    assert.ok(c.plan!.scenarios.flatMap((s) => s.steps).every((st) => st.kind !== "server" || !("expect" in st)), "server replies are judged by the evaluator");
    const spec: TestFlightSpec = { version: "1.21.11", plugins: [{ remotePath: "/tank/nxeon-build/tmp/testflight/inbox/x/K.jar" }], rcon: [{ id: "plugins", command: "plugins", expect: ["Kitchen"] }] };
    const flown = withOracle(spec, c);
