    assert.equal(flown.rcon![0].id, "plugins", "the boot checks stay first and unchanged");
    const used = withOracle({ ...spec, playtest: { schema: 1, scenarios: [{ id: "T-901", steps: [{ kind: "command", text: "/a" }, { kind: "expect_chat", contains: ["a"] }] }] } }, compileOracle(kitchen().exps, { usedScenarioIds: ["T-901"], budgetSec: 120 }));
    const ids = used.playtest!.scenarios.map((s) => s.id);
    assert.equal(new Set(ids).size, ids.length);
  });
  it("time cap: a small budget flies fewer scenarios and reports the rest as not_run (never pass)", () => {
