});

describe("suspect the oracle: a golden and a mutant for every expectation kind", () => {
  it("golden: a working mod passes every testable expectation of the kitchen sink and the plain mod", () => {
    const { exps, c } = kitchen();
    const f = judge(exps, c, simulate(c));
    const bad = f.expectations.filter((e) => e.status !== "pass" && e.status !== "not_testable");
    assert.deepEqual(bad.map((e) => `${e.id} ${e.kind} ${e.status} ${e.reason}`), []);
    assert.equal(f.verdict, "passed");
    assert.equal(f.score, 1);
    const pe = deriveExpectations(PLAIN, { env: {} }), pc = compileOracle(pe);
    const pf = evaluateOracle(pe, pc, simulate(pc), { pluginName: "Plain", version: "1.21.11" });
    assert.deepEqual(pf.expectations.map((e) => e.status), ["pass", "pass", "pass", "pass"]);
  });

  // one mutant per kind: break the KEY observation of that expectation and nothing else
  const kinds = EXPECTATION_KINDS.filter((k) => !["creature_spawns", "model_extra"].includes(k));
  for (const kind of kinds) {
    it(`mutant ${kind}: one defect fails it, the others still pass`, () => {
      const input = kind === "reload_command" ? PLAIN : KITCHEN;
      const exps = deriveExpectations(input, { env: {} }), c = compileOracle(exps, { budgetSec: 120 });
      const target = exps.find((e) => e.kind === kind && e.probe)!;
      assert.ok(target, `no testable ${kind}`);
      const p = partsOf(c, target.id);
      const o: Over = {};
      if (kind === "mod_enables") o.enabled = false;
      else {
        // the last check/probe/act of the expectation is its key observation
        const key = [...p.steps].reverse().find((s) => s.role === "check" || s.role === "probe" || s.role === "act");
        const rkey = [...p.rcon].reverse().find((s) => s.role === "check" || s.role === "probe" || s.role === "act");
        if (key) o.step = { [key.key]: key.want ? { reply: "Unknown or incomplete command, see below for error" } : { status: "fail", ev: "LACKS it" } };
        else if (rkey) o.rcon = { [rkey.id]: "An internal error occurred while attempting to perform this command" };
        else assert.fail(`${kind}: nothing to mutate`);
      }
      const f = evaluateOracle(exps, c, simulate(c, o), { pluginName: input.pluginName, version: "1.21.11" });
      assert.equal(statusOf(f, target.id), "fail", `${kind}: ${JSON.stringify(f.expectations.find((e) => e.id === target.id))}`);
      assert.equal(f.verdict, "failed");
      const others = f.expectations.filter((e) => e.id !== target.id && e.status === "fail" && !(kind === "mod_enables"));
      // a config_reload rides on its host: breaking the host's key check may block (not_run) the attached one, never fail it
      assert.deepEqual(others.map((e) => e.id), [], `${kind}: collateral failures`);
    });
  }

  it("creature_spawns is never a pass in oracle-1 (always not_testable, with the reason)", () => {
    const { exps, c } = kitchen();
    const f = judge(exps, c, simulate(c));
    const cr = f.expectations.find((e) => e.kind === "creature_spawns")!;
    assert.equal(cr.status, "not_testable");
  });
  it("model_extra: golden passes, its mutant fails", () => {
    const exps = deriveExpectations({ ...KITCHEN, extra: [{ title: "Says hi", steps: [{ kind: "command", text: "/kitchen" }, { kind: "expect_chat", contains: ["items"] }] }] }, { env: { CYRUS_TESTFLIGHT_ORACLE_EXTRAS: "1" } });
    const c = compileOracle(exps, { budgetSec: 120 });
    const x = exps.find((e) => e.kind === "model_extra")!;
    assert.equal(statusOf(judge(exps, c, simulate(c)), x.id), "pass");
    const k = partsOf(c, x.id).steps.find((s) => s.role === "check")!;
    assert.equal(statusOf(judge(exps, c, simulate(c, { step: { [k.key]: { status: "fail" } } })), x.id), "fail");
  });
  it("config_reload: the host passing with the old value but missing the marker is a FAIL of the reload only", () => {
    const { exps, c } = kitchen();
    const cr = exps.find((e) => e.kind === "config_reload")!;
    const host = exps.find((e) => e.id === cr.probe!.bot!.attachTo)!;
    const k = partsOf(c, cr.id).steps.find((s) => s.role === "check")!;
    const f = judge(exps, c, simulate(c, { step: { [k.key]: { status: "fail", ev: 'window "Shop" open' } } }));
    assert.equal(statusOf(f, cr.id), "fail");
    assert.equal(statusOf(f, host.id), "pass");
    // and when the host itself fails, the reload is not blamed (not_run: the test it rides on did not pass)
    const hk = partsOf(c, host.id).steps.find((s) => s.role === "check")!;
    const g = judge(exps, c, simulate(c, { step: { [hk.key]: { status: "fail" } } }));
    assert.equal(statusOf(g, host.id), "fail");
    assert.equal(statusOf(g, cr.id), "not_run");
  });
});

describe("evaluate: never claims more than ran", () => {
  it("a failed SETUP step is not_run (the mod is not blamed); a server error while it ran is a fail", () => {
    const { exps, c } = kitchen();
    const ab = exps.find((e) => e.kind === "ability_effect" && e.probe && e.title.includes("Smite"))!;
    const setup = partsOf(c, ab.id).steps.find((s) => s.role === "setup" && s.want)!;
    const f = judge(exps, c, simulate(c, { step: { [setup.key]: { reply: "Unable to summon entity" } } }));
    assert.equal(statusOf(f, ab.id), "not_run");
    assert.match(f.expectations.find((e) => e.id === ab.id)!.reason!, /could not be set up/);
    const sc = c.map[ab.id].scenario!;
    const g = judge(exps, c, simulate(c, { logHit: sc }));
    assert.equal(statusOf(g, ab.id), "fail");
    assert.match(g.expectations.find((e) => e.id === ab.id)!.reason!, /server logged an error/);
  });
  it("busy runner, a bot that never joined, an oracle that did not fly: not_run with the reason, verdict not_run", () => {
    const { exps, c } = kitchen();
    const busy = judge(exps, c, simulate(c, { status: "busy" }));
    assert.equal(busy.verdict, "not_run");
    assert.equal(busy.counts.passed + busy.counts.failed, 0);
    assert.equal(busy.score, null);
    const nj = judge(exps, c, simulate(c, { joined: false }));
    const botOnly = exps.filter((e) => e.probe?.bot && !e.probe.rcon?.length);
    for (const e of botOnly) assert.equal(statusOf(nj, e.id), "not_run");
    assert.ok(nj.expectations.find((e) => e.id === botOnly[0].id)!.reason!.includes("could not join"));
    const none = evaluateOracle(exps, null, simulate(c), { pluginName: "Kitchen", version: "1.21.11" });
    assert.equal(none.verdict, "not_run");
  });
  it("rcon evidence lines parse (ok, optional, error)", () => {
    const lines = ["nxo-e2-1 'kitchen' [rss 1 MB, 2 ms]: ok (optional) -> Kitchen: items wand", "nxo-e3-1 'x': ERROR rcon timeout after 10000 ms"];
    assert.deepEqual(rconLine(lines, "nxo-e2-1")!.reply, "Kitchen: items wand");
    assert.equal(rconLine(lines, "nxo-e3-1")!.state, "error");
    assert.equal(rconLine(lines, "nxo-e9-1"), null);
  });
  it("planOracle isolates oracle problems: an invalid probe returns the ORIGINAL spec and a not_run record", () => {
    const spec: TestFlightSpec = { version: "1.21.11", plugins: [{ remotePath: "/tank/nxeon-build/tmp/testflight/inbox/x/K.jar" }], rcon: [] };
    const ok = planOracle(KITCHEN, spec, { env: {} });
    assert.equal(ok.ok, true);
    const bad = planOracle({ ...KITCHEN, pluginYml: PLUGIN_YML.replace("kitchen:", "stop:") }, spec, { env: {} });
    // a reserved command name makes the console probe invalid -> the oracle stands down, the flight is untouched
    assert.equal(bad.ok, false);
    assert.equal(bad.spec, spec);
    if (!bad.ok) assert.match(bad.record.reason!, /oracle error/);
    const thrown = planOracle({ ...KITCHEN, designs: [{ name: "x", spec: { get abilities() { throw new Error("boom"); }, id: "x", base: "stone" } }] } as OracleInput, spec, { env: {} });
    assert.equal(thrown.spec, spec);
    assert.equal(judgeOracle(thrown, null, { pluginName: "K", version: "1.21.11" }).verdict, "not_run");
  });
  it("the owner panel: failures first, plain words, never a pass for not-run", () => {
    const { exps, c } = kitchen();
    const target = exps.find((e) => e.kind === "menu_opens")!;
    const k = partsOf(c, target.id).steps.find((s) => s.role === "check")!;
    const f = judge(exps, c, simulate(c, { step: { [k.key]: { status: "fail" } } }));
    const p = verifiedPanel({ functional: f })!;
    assert.equal(p.tone, "bad");
    assert.equal(p.rows[0].word, "did not work");
    assert.ok(!JSON.stringify(p).match(/rcon|mineflayer|RCON|scenario|T-9/));
    assert.equal(verifiedPanel({ functional: { bad: true } }), null);
    assert.equal(verifiedPanel(null), null);
    const nr = verifiedPanel({ functional: judge(exps, c, simulate(c, { status: "busy" })) })!;
    assert.equal(nr.headline, "Behaviour not tested yet");
    assert.ok(readFunctional(f));
  });
});

describe("gate wiring (CYRUS_TESTFLIGHT_ORACLE)", () => {
  const build = { id: "mbx", mcVersion: "1.21.11", pluginName: "Kitchen", jarSha256: null, result: { commands: [{ usage: "/kitchen" }], safety: { verdict: "pass" } }, cyrus: {} };
  const deps = (env: Record<string, string>, run: GateDeps["run"], stored: unknown[]): GateDeps => ({
    env, candidates: async () => [], artifacts: async () => ({ jarPath: "/tmp/x.jar", datapacks: [] }), run,
    store: async (_id, f) => { stored.push(f); }, oracleInput: async () => KITCHEN,
  });
  it("off: nothing changes (no functional key); on: same boot verdict, functional stored, the boot spec untouched", async () => {
    const specs: TestFlightSpec[] = [];
    const run: GateDeps["run"] = async (spec) => {
      specs.push(spec);
      const c = compileOracle(deriveExpectations(KITCHEN, { env: {} }));
      const r = simulate(c);
      r.checks.unshift({ id: "boot_done", status: "pass", required: true, durationMs: 1, evidence: ["Done (5s)"] });
      for (const id of ["startup_log_clean", "clean_stop", "no_leaks"] as const) r.checks.push({ id, status: "pass", required: true, durationMs: 1, evidence: ["ok"] });
      r.checks.find((x) => x.id === "rcon_checks")!.evidence.unshift("plugins 'plugins' [rss 1 MB, 1 ms]: ok -> Plugins (1): Kitchen", "cmd-kitchen 'help kitchen' [rss 1 MB, 1 ms]: ok (optional) -> help");
      const { summarize } = await import("../lib/cyrus/testflight/summary");
      return { report: r, summary: summarize(spec, r), resolved: {} as never, stderr: "" };
    };
    const off: unknown[] = [];
    await flyOne(build, null, deps({ CYRUS_TESTFLIGHT_GATE: "1" }, run, off), () => new Date(0));
    const a = off[off.length - 1] as { verdict: string; functional?: unknown };
    assert.equal(a.functional, undefined);
    assert.equal(specs[0].playtest, undefined);
    const on: unknown[] = [];
    await flyOne(build, null, deps({ CYRUS_TESTFLIGHT_GATE: "1", CYRUS_TESTFLIGHT_ORACLE: "1" }, run, on), () => new Date(0));
    const b = on[on.length - 1] as { verdict: string; label: string | null; functional?: { stage: string; verdict: string } };
    assert.equal(b.verdict, a.verdict, "the boot verdict never depends on the oracle");
    assert.equal(b.functional?.stage, "behaviour");
    assert.ok(specs[1].playtest && specs[1].rcon!.some((r) => r.id!.startsWith("nxo-")));
  });
  it("a runner that refuses the oracle's probes: the plugin is flown again without them, the oracle is not_run", async () => {
    const specs: TestFlightSpec[] = [];
    const run: GateDeps["run"] = async (spec) => {
      specs.push(spec);
      if (spec.playtest) throw new Error("runner refused the spec: {\"error\":\"playtest.scenarios[0].steps[1].kind must be one of ...\"}");
      const r = simulate(compileOracle([]));
      const { summarize } = await import("../lib/cyrus/testflight/summary");
      return { report: r, summary: summarize(spec, r), resolved: {} as never, stderr: "" };
    };
    const st: unknown[] = [];
    await flyOne(build, null, deps({ CYRUS_TESTFLIGHT_GATE: "1", CYRUS_TESTFLIGHT_ORACLE: "1" }, run, st), () => new Date(0));
    assert.equal(specs.length, 2);
    assert.equal(specs[1].playtest, undefined);
    const last = st[st.length - 1] as { state: string; functional: { verdict: string; reason: string } };
    assert.equal(last.state, "done");
    assert.equal(last.functional.verdict, "not_run");
    assert.match(last.functional.reason, /oracle error/);
  });
});

