    assert.ok(!exps.some((e) => e.kind === "model_extra"));
    const withExtra = deriveExpectations({ ...KITCHEN, extra: [{ title: "Says hi", steps: [{ kind: "command", text: "/kitchen" }, { kind: "expect_chat", contains: ["items"] }] }] }, { env: { CYRUS_TESTFLIGHT_ORACLE_EXTRAS: "1" } });
    const x = withExtra.find((e) => e.kind === "model_extra")!;
