#!/usr/bin/env tsx
// Behaviour oracle on REAL builds: one Test Flight per build on node-2 with the oracle's probes (lib/cyrus/testflight/oracle),
// exactly the gate's flight + the oracle. Run from a worktree on the primary (only ssh to node-2; the server boots there).
// Respects node-2's shared build lock (/run/lock/nxeon-build.lock is held for each flight) and the runner's own lock.
//
//   npx tsx scripts/cyrus/oracle-flight.ts --builds DIR [--keys a,b] [--out FILE] [--budget 45]
//        DIR holds <key>.jar + <key>.build.json (GET /builds/<id>/artifact and GET /builds/<id> of the build service)
//   npx tsx scripts/cyrus/oracle-flight.ts --goldens mc-kits,mc-shop [--out FILE]      golden jars already on node-2
//   npx tsx scripts/cyrus/oracle-flight.ts --builds DIR --mutant shop-gui:count ...    a deliberately broken variant
//   --engine-from /tank/dev-worktrees/cyrus-tf-bm   provide BetterModel like fix/cyrus-testflight-bettermodel (until merged)
//
// Mutants (the expectations always come from the ORIGINAL design; the jar flown is broken on purpose):
//   <key>:count   first menu button that gives items gives 1 instead (config.yml)
//   <key>:title   first menu title changed (config.yml)
//   <key>:sound   first ability sound key replaced (config.yml)
//   <key>:main    plugin.yml main class broken (the mod cannot enable: the "compiled, booted, did not enable" class)
import { mkdtempSync, mkdirSync, readFileSync, writeFileSync, rmSync, existsSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { createHash } from "node:crypto";
import { runTestFlight, sshRemote, shq, type Remote } from "../../lib/cyrus/testflight/client";
import { planGateFlight, gateChecks, gateVerdict } from "../../lib/cyrus/testflight/gate";
import { summarize } from "../../lib/cyrus/testflight/summary";
import type { TestFlightSpec } from "../../lib/cyrus/testflight/types";
import { planOracle, judgeOracle } from "../../lib/cyrus/testflight/oracle/run";
import { inputFromServiceRecord, jarTexts } from "../../lib/cyrus/testflight/oracle/inputs";
import type { OracleInput } from "../../lib/cyrus/testflight/oracle/types";
import { buildDataPack } from "../../lib/cyrus/datapack/emit";
import { setYamlValue, getYamlValue } from "../../lib/cyrus/config/yamldoc";
import { DEFAULT_ZIP_LIMITS, indexZip, readEntry } from "../../lib/cyrus/inventory/zipread";
import { zip } from "../../lib/cyrus/textures/zip";

const argv = process.argv.slice(2);
const opt = (n: string, d = "") => { const i = argv.indexOf(`--${n}`); return i >= 0 && argv[i + 1] && !argv[i + 1].startsWith("--") ? argv[i + 1] : d; };
const opts = (n: string) => argv.flatMap((a, i) => (a === `--${n}` && argv[i + 1] ? [argv[i + 1]] : []));
const list = (s: string) => s.split(",").map((x) => x.trim()).filter(Boolean);
const VERSION = opt("version", "1.21.11");
const OUT = opt("out", path.join(process.cwd(), ".cyrus-local", "oracle", `oracle-flights-${Date.now()}.json`));
const BUDGET = parseInt(opt("budget", "45"), 10);
const sha = (b: Buffer) => createHash("sha256").update(b).digest("hex");

/** The runner command holds node-2's shared build lock while it flies (other heavy jobs wait, and we wait for them). */
function lockedRemote(): Remote {
  const base = sshRemote();
  return {
    exec: (command, o) => {
      if (!/runner\.js'? run /.test(command)) return base.exec(command, o);
      return base.exec(`flock -w 1500 /run/lock/nxeon-build.lock sh -c ${shq(command)}`, { ...o, timeoutMs: (o?.timeoutMs ?? 600000) + 1500000 });
    },
  };
}
const REMOTE = lockedRemote();
async function flyWhenFree(spec: TestFlightSpec) {
  for (let i = 0; ; i++) {
    const r = await runTestFlight(spec, { remote: REMOTE });
    if (r.report.status !== "busy" || i >= 40) return r;
    console.log("  node-2 busy (another flight): waiting 30 s");
    await new Promise((res) => setTimeout(res, 30000));
  }
}

/** Rewrite one entry of a jar (deterministic zip). */
function patchJar(jar: Buffer, name: string, edit: (t: string) => string): Buffer {
  const idx = indexZip(jar, DEFAULT_ZIP_LIMITS);
  if (!idx.ok) throw new Error("jar unreadable");
  const files: { path: string; data: Buffer }[] = [];
  for (const e of idx.zip.entries) {
    if (e.dir) continue;
    const r = readEntry(idx.zip, e, 8 * 1024 * 1024);
    if (!r.ok) throw new Error(`cannot read ${e.name}`);
    files.push({ path: e.name, data: e.name === name ? Buffer.from(edit(r.data.toString("utf8"))) : r.data });
  }
  return zip(files);
}

type Rec = { id: string; pluginName?: string | null; mcVersion?: string; jar?: { sha256?: string } | null; assetResult?: Record<string, unknown> | null; commands?: unknown; safety?: unknown };

function mutate(kind: string, jar: Buffer, input: OracleInput): { jar: Buffer; note: string } {
  const designs = input.designs ?? [];
  const cfg = jarTexts(jar).configYml ?? "";
  const set = (p: string, v: string | number) => { const r = setYamlValue(cfg, p, v); if (!r.ok || !r.changed) throw new Error(`cannot set ${p}`); return r.text; };
  if (kind === "main") return { jar: patchJar(jar, "plugin.yml", (t) => t.replace(/^main: .*$/m, "main: dev.nxeon.plugins.broken.DoesNotExist")), note: "plugin.yml main class broken" };
  if (kind === "count" || kind === "title") {
    for (const d of designs) {
      const m = d.spec as { kind?: string; id: string; buttons?: { slot: number; actions?: { type: string }[] }[] };
      if (m.kind !== "menu") continue;
      if (kind === "title" && getYamlValue(cfg, `menus.${m.id}.title`).found) return { jar: patchJar(jar, "config.yml", () => set(`menus.${m.id}.title`, "Something Else")), note: `menus.${m.id}.title -> "Something Else"` };
      for (const b of m.buttons ?? []) {
        const i = (b.actions ?? []).findIndex((a) => a.type === "give_item");
        const p = `menus.${m.id}.b${b.slot}.a${i}.count`;
        if (kind === "count" && i >= 0 && getYamlValue(cfg, p).found) return { jar: patchJar(jar, "config.yml", () => set(p, 1)), note: `${p} -> 1` };
      }
    }
  }
  if (kind === "sound") {
    const m = /^(\s*)sound: "([^"]+)"/m.exec(cfg);
    if (m) return { jar: patchJar(jar, "config.yml", (t) => t.replace(m[0], `${m[1]}sound: "minecraft:block.note_block.pling"`)), note: `first sound key ${m[2]} -> minecraft:block.note_block.pling` };
  }
  throw new Error(`no ${kind} mutation applies to this build`);
}

async function engineFor(jar: Buffer, rec: Rec, dir: string) {
  const from = opt("engine-from");
  if (!from) return null;
  const mod = await import(path.join(from, "lib/cyrus/testflight/engine"));
  const creatures = (rec.assetResult?.creatures as { spec?: unknown }[] | undefined) ?? [];
  const p = await mod.provisionEngine({ jar, mcVersion: VERSION, namespace: rec.assetResult?.namespace ?? null, creatures: creatures.map((c) => ({ ...c, spec: c.spec })) });
  if (!p || p.unavailable || !p.jar) return p ? { name: p.name, unavailable: p.unavailable ?? "no jar" } : null;
  const lp = path.join(dir, "BetterModel.jar");
  writeFileSync(lp, p.jar.bytes);
  return { name: p.name as string, localPath: lp, sha256: p.jar.sha256 as string, seeds: p.seeds ?? [], files: p.files ?? [], notes: p.notes ?? [] };
}

async function flyBuild(key: string, jar0: Buffer, rec: Rec, mutant: string | null) {
  const dir = mkdtempSync(path.join(tmpdir(), "cyrus-oracle-"));
  try {
    let input = inputFromServiceRecord(rec, jar0, VERSION);
    let jar = jar0, mutNote: string | null = null;
    if (mutant) { const m = mutate(mutant, jar0, input); jar = m.jar; mutNote = m.note; }
    const jarPath = path.join(dir, `${rec.pluginName ?? key}.jar`);
    writeFileSync(jarPath, jar);
    // data packs: rebuilt from the stored spec exactly like the gate does at delivery
    const ns = (rec.assetResult?.namespace as string | undefined) ?? "";
    const datapacks: { name: string; localPath: string }[] = [];
    for (const d of (rec.assetResult?.datapacks as { name: string; spec: unknown; pack?: { worldgen?: unknown } }[] | undefined) ?? []) {
      const b = buildDataPack(d.spec, { version: VERSION, namespace: ns, worldgen: !!d.pack?.worldgen || JSON.stringify(d.spec).includes('"dimension_type"') });
      if (!b.ok) { console.log(`  data pack ${d.name} does not rebuild: ${b.errors[0]}`); continue; }
      const name = `nxeon-${ns}-${b.pack.name}`.toLowerCase().replace(/[^a-z0-9_.-]/g, "-").slice(0, 64);
      const p = path.join(dir, `${name}.zip`); writeFileSync(p, b.pack.zip);
      datapacks.push({ name, localPath: p });
    }
    const eng = await engineFor(jar, rec, dir);
    // the oracle reads the jar it flies (a mutant's config is what the server has), the designs from the build record
    input = { ...inputFromServiceRecord(rec, jar, VERSION, { datapacksFlown: (rec.assetResult?.datapacks as { name: string }[] | undefined ?? []).map((d) => d.name).filter(() => datapacks.length > 0), engines: eng && "localPath" in eng ? [eng.name] : [] }) };
    const b = { id: rec.id, mcVersion: VERSION, pluginName: rec.pluginName ?? null, jarSha256: sha(jar), result: rec };
    const plan = planGateFlight(b, { jarPath, datapacks });
    if (!plan.ok) return { key, buildId: rec.id, mutant, error: plan.reason };
    let spec = plan.spec;
    if (eng && "localPath" in eng && eng.localPath) {
      spec = { ...spec, plugins: [{ localPath: eng.localPath, sha256: eng.sha256 }, ...(spec.plugins ?? [])], files: [...(spec.files ?? []), ...eng.files], seeds: eng.seeds, memory: { xmxMb: 1024, rssCapMb: 2048 }, timeouts: { bootSec: 300, rconSec: 30, stopSec: 90, totalSec: 600 } };
    }
    const bootSpec = spec;
    const oracle = planOracle(input, spec, { budgetSec: BUDGET });
    if (!oracle.ok) console.log(`  oracle not flown: ${oracle.record.reason}`);
    const t0 = Date.now();
    const res = await flyWhenFree(oracle.ok ? oracle.spec : spec);
    const wallMs = Date.now() - t0;
    const boot = summarize(bootSpec, res.report);
    const checks = gateChecks(b, res.report, boot, { commands: plan.commands, datapacks: datapacks.length });
    const verdict = gateVerdict(boot, checks);
    const functional = judgeOracle(oracle, res.report, { pluginName: rec.pluginName ?? "", version: VERSION });
    const raw = path.join(path.dirname(OUT), "reports");
    mkdirSync(raw, { recursive: true });
    writeFileSync(path.join(raw, `${key}${mutant ? `.${mutant}` : ""}.report.json`), JSON.stringify({ report: res.report, flown: oracle.ok ? oracle.spec : spec, map: oracle.ok ? oracle.compiled.map : null }, null, 1));
    return {
      key, buildId: rec.id, mutant, mutation: mutNote, runId: res.report.runId, wallMs, bootMs: res.report.bootMs, peakRssKb: res.report.peakRssKb,
      boot: { verdict: verdict.verdict, checks: checks.map((c) => `${c.id}:${c.status}`) },
      oracleTiming: oracle.ok ? oracle.compiled.timing : null, engine: eng ? ("localPath" in eng ? eng.name : `unavailable: ${eng.unavailable}`) : null,
      functional,
    };
  } finally { rmSync(dir, { recursive: true, force: true }); }
}

async function main() {
  mkdirSync(path.dirname(OUT), { recursive: true });
  const results: unknown[] = existsSync(OUT) ? JSON.parse(readFileSync(OUT, "utf8")) : [];
  const save = () => writeFileSync(OUT, JSON.stringify(results, null, 1) + "\n");
  const dir = opt("builds");
  const keys = opt("keys") ? list(opt("keys")) : [];
  const mutants = opts("mutant");
  const show = (r: { key: string; mutant: string | null; functional?: { label: string; expectations: { id: string; kind: string; status: string; title: string; reason: string | null }[] }; boot?: { verdict: string }; wallMs?: number; error?: string }) => {
    console.log(`== ${r.key}${r.mutant ? ` [mutant ${r.mutant}]` : ""}: boot ${r.boot?.verdict ?? "-"}, ${r.functional?.label ?? r.error} (${Math.round((r.wallMs ?? 0) / 1000)} s)`);
    for (const e of r.functional?.expectations ?? []) console.log(`   ${e.status.padEnd(12)} ${e.id} ${e.kind}: ${e.title}${e.reason ? `  -- ${e.reason}` : ""}`);
  };
  if (dir) {
    const targets = mutants.length ? mutants.map((m) => ({ key: m.split(":")[0], mutant: m.split(":")[1] })) : keys.map((k) => ({ key: k, mutant: null as string | null }));
    for (const t of targets) {
      const rec = JSON.parse(readFileSync(path.join(dir, `${t.key}.build.json`), "utf8")) as Rec;
      const jar = readFileSync(path.join(dir, `${t.key}.jar`));
      console.log(`flying ${t.key}${t.mutant ? ` (mutant ${t.mutant})` : ""} (${rec.id})`);
      try { const r = await flyBuild(t.key, jar, rec, t.mutant); results.push(r); show(r as never); }
      catch (e) { results.push({ key: t.key, mutant: t.mutant, error: (e as Error).message }); console.log(`  error: ${(e as Error).message}`); }
      save();
    }
  }
  for (const g of opt("goldens") ? list(opt("goldens")) : []) {
    // golden jars are compiled on node-2 by the golden harness: fetch one, fly it like a build (no designs)
    const remote = `/tank/nxeon-build/tmp/testflight/mc-coverage/${VERSION}/${g}.jar`;
    const r = await REMOTE.exec(`base64 -w0 ${shq(remote)}`, { timeoutMs: 60000 });
    if (r.code !== 0) { results.push({ key: g, error: `no golden jar ${remote}` }); continue; }
    const jar = Buffer.from(r.stdout.trim(), "base64");
    const name = /^name: *'?([A-Za-z0-9_.-]+)/m.exec(jarTexts(jar).pluginYml ?? "")?.[1] ?? g;
    const cmds = [...(jarTexts(jar).pluginYml ?? "").matchAll(/^ {2}([a-z0-9_-]+):\s*$/gm)].map((m) => ({ usage: `/${m[1]}` }));
    console.log(`flying golden ${g} (${name})`);
    try { const x = await flyBuild(g, jar, { id: `golden-${g}`, pluginName: name, commands: cmds, safety: { verdict: "pass" }, assetResult: null }, null); results.push(x); show(x as never); }
    catch (e) { results.push({ key: g, error: (e as Error).message }); console.log(`  error: ${(e as Error).message}`); }
    save();
  }
  console.log(`wrote ${OUT}`);
}

main().catch((e) => { console.error(`oracle-flight: ${(e as Error).stack ?? e}`); process.exit(2); });

