    writeFileSync(path.join(raw, `${key}${mutant ? `.${mutant}` : ""}.report.json`), JSON.stringify({ report: res.report, flown: oracle.ok ? oracle.spec : spec, map: oracle.ok ? oracle.compiled.map : null }, null, 1));
