      key, buildId: rec.id, mutant, mutation: mutNote, runId: res.report.runId, wallMs, bootMs: res.report.bootMs, peakRssKb: res.report.peakRssKb,
      boot: { verdict: verdict.verdict, checks: checks.map((c) => `${c.id}:${c.status}`) },
      oracleTiming: oracle.ok ? oracle.compiled.timing : null, engine: eng ? ("localPath" in eng ? eng.name : `unavailable: ${eng.unavailable}`) : null,
      functional,
    };
  } finally { rmSync(dir, { recursive: true, force: true }); }
}

async function main() {
  mkdirSync(path.dirname(OUT), { recursive: true });
  const results: unknown[] = existsSync(OUT) ? JSON.parse(readFileSync(OUT, "utf8")) : [];
  const save = () => writeFileSync(OUT, JSON.stringify(results, null, 1) + "\n");
  const dir = opt("builds");
  const keys = opt("keys") ? list(opt("keys")) : [];
  const mutants = opts("mutant");
  const show = (r: { key: string; mutant: string | null; functional?: { label: string; expectations: { id: string; kind: string; status: string; title: string; reason: string | null }[] }; boot?: { verdict: string }; wallMs?: number; error?: string }) => {
    console.log(`== ${r.key}${r.mutant ? ` [mutant ${r.mutant}]` : ""}: boot ${r.boot?.verdict ?? "-"}, ${r.functional?.label ?? r.error} (${Math.round((r.wallMs ?? 0) / 1000)} s)`);
    for (const e of r.functional?.expectations ?? []) console.log(`   ${e.status.padEnd(12)} ${e.id} ${e.kind}: ${e.title}${e.reason ? `  -- ${e.reason}` : ""}`);
  };
  if (dir) {
    const targets = mutants.length ? mutants.map((m) => ({ key: m.split(":")[0], mutant: m.split(":")[1] })) : keys.map((k) => ({ key: k, mutant: null as string | null }));
    for (const t of targets) {
      const rec = JSON.parse(readFileSync(path.join(dir, `${t.key}.build.json`), "utf8")) as Rec;
      const jar = readFileSync(path.join(dir, `${t.key}.jar`));
      console.log(`flying ${t.key}${t.mutant ? ` (mutant ${t.mutant})` : ""} (${rec.id})`);
      try { const r = await flyBuild(t.key, jar, rec, t.mutant); results.push(r); show(r as never); }
      catch (e) { results.push({ key: t.key, mutant: t.mutant, error: (e as Error).message }); console.log(`  error: ${(e as Error).message}`); }
      save();
    }
  }
  for (const g of opt("goldens") ? list(opt("goldens")) : []) {
    // golden jars are compiled on node-2 by the golden harness: fetch one, fly it like a build (no designs)
    const remote = `/tank/nxeon-build/tmp/testflight/mc-coverage/${VERSION}/${g}.jar`;
    const r = await REMOTE.exec(`base64 -w0 ${shq(remote)}`, { timeoutMs: 60000 });
    if (r.code !== 0) { results.push({ key: g, error: `no golden jar ${remote}` }); continue; }
    const jar = Buffer.from(r.stdout.trim(), "base64");
    const name = /^name: *'?([A-Za-z0-9_.-]+)/m.exec(jarTexts(jar).pluginYml ?? "")?.[1] ?? g;
    const cmds = [...(jarTexts(jar).pluginYml ?? "").matchAll(/^ {2}([a-z0-9_-]+):\s*$/gm)].map((m) => ({ usage: `/${m[1]}` }));
    console.log(`flying golden ${g} (${name})`);
    try { const x = await flyBuild(g, jar, { id: `golden-${g}`, pluginName: name, commands: cmds, safety: { verdict: "pass" }, assetResult: null }, null); results.push(x); show(x as never); }
    catch (e) { results.push({ key: g, error: (e as Error).message }); console.log(`  error: ${(e as Error).message}`); }
    save();
  }
  console.log(`wrote ${OUT}`);
}

main().catch((e) => { console.error(`oracle-flight: ${(e as Error).stack ?? e}`); process.exit(2); });

